-- QA-ONLY. Official NCA catalog data correction: upserts the full
-- validated Master Catalog (nca_reconciliation/framework_catalogs/*.md) into
-- public.controls by (framework, control_code). For codes already present,
-- this UPDATES only official_text_ar / hierarchy_level / source_page /
-- applicability — title_ar, implementation_status, evidence_status,
-- verification_status, control_owner*, due_date, and every other
-- operational column are left untouched, and the row's id (and therefore
-- every FK relationship to it) is preserved unconditionally. For codes not
-- yet present, this INSERTS a new row (fresh id) with a concise
-- display-label title_ar (matching the existing "{subdomain} - {code}"
-- convention) and the real official_text_ar — never a synthetic
-- regulatory text.
--
-- parent_control_id is populated in a second pass below, once every row
-- (including newly inserted parents) has a real id.
--
-- Idempotent: safe to re-run. Deterministic: driven entirely by
-- (framework code, official control_code), never by hardcoded numeric ids.
-- Does not touch the QA_SYNTH framework or its 3 rows, and does not touch
-- any evidence/evidence_requests/control_review_cycles/control_assessments/
-- profiles/pilot data.

-- 1) Framework metadata: source_url + ensure all 6 frameworks exist (QA is
--    missing OSMACC entirely).
insert into public.frameworks (code, name_ar, name_en, version, description_ar, is_active, source_url)
values
  ('ECC', 'الضوابط الأساسية للأمن السيبراني', 'Essential Cybersecurity Controls', '2-2024', 'الضوابط الأساسية للأمن السيبراني الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa/api/files/public/upload/e4c81aa9-a609-4823-abab-347283e29731_ECC-2-2024-AR-19092024-.pdf'),
  ('DCC', 'ضوابط الأمن السيبراني للبيانات', 'Data Cybersecurity Controls', '1-2022', 'ضوابط الأمن السيبراني للبيانات الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa/api/files/public/upload/32bf3911-3c6d-4802-af66-773c2174aee5_DCC-.pdf'),
  ('CSCC', 'ضوابط الأمن السيبراني للأنظمة الحساسة', 'Critical Systems Cybersecurity Controls', '1-2019', 'ضوابط الأمن السيبراني للأنظمة الحساسة الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa/ar/cscc-ar.pdf'),
  ('TCC', 'ضوابط الأمن السيبراني للعمل عن بعد', 'Telework Cybersecurity Controls', '1-2021', 'ضوابط الأمن السيبراني للعمل عن بعد الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa'),
  ('OSMACC', 'ضوابط الأمن السيبراني لحسابات التواصل الاجتماعي للجهات', 'Organizations'' Social Media Accounts Cybersecurity Controls', '1-2021', 'ضوابط الأمن السيبراني لحسابات التواصل الاجتماعي للجهات الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa'),
  ('CCC', 'ضوابط الأمن السيبراني للحوسبة السحابية', 'Cloud Cybersecurity Controls', '2-2024', 'ضوابط الأمن السيبراني للحوسبة السحابية الصادرة عن الهيئة الوطنية للأمن السيبراني', true, 'https://cdn.nca.gov.sa/api/files/public/upload/bd85b958-45a7-4b65-8eb1-cc1361c91233_CCC-2-2024-.pdf')
on conflict (code) do update set source_url = excluded.source_url, version = excluded.version;

-- 2) Controls: upsert all 664 official leaf regulatory items.
with catalog(framework_code, control_code, title_ar, official_text_ar, domain_ar, hierarchy_level, source_page, applicability, parent_code) as (
  values
  ('ECC', '1-1-1', 'إستراتيجية الأمن السيبراني - 1-1-1', 'يجب تحديد وتوثيق واعتماد إستراتيجية الأمن السيبراني للجهة ودعمها من قبل رئيس الجهة أو من ينيبه (ويشار له في هذه الضوابط باسم "صاحب الصلاحية")، وأن تتماشى الأهداف الإستراتيجية للأمن السيبراني للجهة مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-1-2', 'إستراتيجية الأمن السيبراني - 1-1-2', 'يجب العمل على تنفيذ خطة عمل لتطبيق إستراتيجية الأمن السيبراني من قبل الجهة.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-1-3', 'إستراتيجية الأمن السيبراني - 1-1-3', 'يجب مراجعة إستراتيجية الأمن السيبراني على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-10-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-1', 'يجب تطوير واعتماد برنامج للتوعية بالأمن السيبراني في الجهة من خلال قنوات متعددة دورياً، وذلك لتعزيز الوعي بالأمن السيبراني وتهديداته ومخاطره، وبناء ثقافة إيجابية للأمن السيبراني.', 'حوكمة الأمن السيبراني', 'control', '17-18', NULL, NULL),
  ('ECC', '1-10-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-2', 'يجب تطبيق البرنامج المعتمد للتوعية بالأمن السيبراني في الجهة.', 'حوكمة الأمن السيبراني', 'control', '17-18', NULL, NULL),
  ('ECC', '1-10-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3', 'يجب أن يغطي برنامج التوعية بالأمن السيبراني كيفية حماية الجهة من أهم المخاطر والتهديدات السيبرانية وما يستجد منها، بما في ذلك:', 'حوكمة الأمن السيبراني', 'control', '17-18', NULL, NULL),
  ('ECC', '1-10-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3-1', 'التعامل الآمن مع خدمات البريد الإلكتروني خصوصاً مع رسائل التصيد الإلكتروني.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-3'),
  ('ECC', '1-10-3-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3-2', 'التعامل الآمن مع الأجهزة المحمولة ووسائط التخزين.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-3'),
  ('ECC', '1-10-3-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3-3', 'التعامل الآمن مع خدمات تصفح الإنترنت.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-3'),
  ('ECC', '1-10-3-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3-4', 'التعامل الآمن مع وسائل التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-3'),
  ('ECC', '1-10-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-4', 'يجب توفير المهارات والتدريب المتخصصة اللازم للعاملين في المجالات الوظيفية ذات العلاقة المباشرة بالأمن السيبراني في الجهة، وتصنيفها بما يتماشى مع مسؤولياتهم الوظيفية فيما يتعلق بالأمن السيبراني، بما في ذلك:', 'حوكمة الأمن السيبراني', 'control', '17-18', NULL, NULL),
  ('ECC', '1-10-4-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-4-1', 'موظفو الإدارة المعنية بالأمن السيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-4'),
  ('ECC', '1-10-4-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-4-2', 'الموظفون العاملون في تطوير البرامج والتطبيقات والموظفون المشغلون للأصول المعلوماتية والتقنية للجهة.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-4'),
  ('ECC', '1-10-4-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-4-3', 'الوظائف الإشرافية والتنفيذية.', 'حوكمة الأمن السيبراني', 'sub_control', '17-18', NULL, '1-10-4'),
  ('ECC', '1-10-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-5', 'يجب مراجعة تطبيق برنامج التوعية بالأمن السيبراني في الجهة دورياً.', 'حوكمة الأمن السيبراني', 'control', '17-18', NULL, NULL),
  ('ECC', '1-2-1', 'إدارة الأمن السيبراني - 1-2-1', 'يجب إنشاء إدارة معنية بالأمن السيبراني في الجهة (مستقلة عن إدارة تقنية المعلومات والاتصالات (ICT/IT)) (وفقاً للأمر السامي الكريم رقم 37140 وتاريخ 14/8/1438هـ). ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-2-2', 'إدارة الأمن السيبراني - 1-2-2', 'يجب شغل جميع وظائف الأمن السيبراني من قبل مواطنين متفرغين وذوي كفاءة في مجال الأمن السيبراني.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-2-3', 'إدارة الأمن السيبراني - 1-2-3', 'يجب إنشاء لجنة إشرافية للأمن السيبراني بتوجيه من صاحب الصلاحية للجهة لضمان التزام ودعم ومتابعة تطبيق برامج وتشريعات الأمن السيبراني، ويتم تحديد وتوثيق واعتماد أعضاء اللجنة ومسؤولياتها وإطار حوكمة أعمالها على أن يكون رئيس الإدارة المعنية بالأمن السيبراني أحد أعضائها. ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-3-1', 'سياسات وإجراءات الأمن السيبراني - 1-3-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد سياسات وإجراءات الأمن السيبراني وما تشمله من ضوابط ومتطلبات الأمن السيبراني، وتوثيقها واعتمادها من قبل صاحب الصلاحية في الجهة. كما يجب نشرها إلى ذوي العلاقة من العاملين في الجهة والأطراف المعنية بها.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-3-2', 'سياسات وإجراءات الأمن السيبراني - 1-3-2', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة ضمان تطبيق سياسات وإجراءات الأمن السيبراني في الجهة وما تشمله من ضوابط ومتطلبات.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-3-3', 'سياسات وإجراءات الأمن السيبراني - 1-3-3', 'يجب أن تكون سياسات وإجراءات الأمن السيبراني مدعومة بمعايير تقنية أمنية (على سبيل المثال: المعايير التقنية الأمنية لجدار الحماية لقواعد البيانات، وأنظمة التشغيل، إلخ).', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-3-4', 'سياسات وإجراءات الأمن السيبراني - 1-3-4', 'يجب مراجعة سياسات وإجراءات ومعايير الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('ECC', '1-4-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-4-1', 'يجب على صاحب الصلاحية تحديد وتوثيق واعتماد الهيكل التنظيمي للحوكمة والأدوار والمسؤوليات الخاصة بالأمن السيبراني للجهة، وتكليف الأشخاص المعنيين بها، كما يجب تقديم الدعم اللازم لإنفاذ ذلك، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-4-2', 'أدوار ومسؤوليات الأمن السيبراني - 1-4-2', 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني في الجهة وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-5-1', 'إدارة مخاطر الأمن السيبراني - 1-5-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة. وذلك وفقاً لاعتبارات السرية وتوافر وسلامة الأصول المعلوماتية والتقنية.', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-5-2', 'إدارة مخاطر الأمن السيبراني - 1-5-2', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تطبيق منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة.', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-5-3', 'إدارة مخاطر الأمن السيبراني - 1-5-3', 'يجب تنفيذ إجراءات تقييم مخاطر الأمن السيبراني بحد أدنى في الحالات التالية:', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-5-3-1', 'إدارة مخاطر الأمن السيبراني - 1-5-3-1', 'في مرحلة مبكرة من المشاريع التقنية.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-5-3'),
  ('ECC', '1-5-3-2', 'إدارة مخاطر الأمن السيبراني - 1-5-3-2', 'قبل إجراء تغيير جوهري في البنية التقنية.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-5-3'),
  ('ECC', '1-5-3-3', 'إدارة مخاطر الأمن السيبراني - 1-5-3-3', 'عند التخطيط للحصول على خدمات طرف خارجي.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-5-3'),
  ('ECC', '1-5-3-4', 'إدارة مخاطر الأمن السيبراني - 1-5-3-4', 'عند التخطيط وقبل إطلاق منتجات وخدمات تقنية جديدة.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-5-3'),
  ('ECC', '1-5-4', 'إدارة مخاطر الأمن السيبراني - 1-5-4', 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-6-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-1', 'يجب تضمين متطلبات الأمن السيبراني في منهجية وإجراءات إدارة المشاريع وفي إدارة التغيير على الأصول المعلوماتية والتقنية في الجهة لضمان تحديد مخاطر الأمن السيبراني ومعالجتها كجزء من دورة حياة المشروع التقني، وأن تكون متطلبات الأمن السيبراني جزء أساسي من متطلبات المشاريع التقنية.', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-6-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-2', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للجهة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-6-2-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-2-1', 'تقييم الثغرات ومعالجتها.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-2'),
  ('ECC', '1-6-2-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-2-2', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين المشاريع والتغييرات.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-2'),
  ('ECC', '1-6-3', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير التطبيقات والبرمجيات الخاصة للجهة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '16', NULL, NULL),
  ('ECC', '1-6-3-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-3-1', 'استخدام معايير التطوير الآمن للتطبيقات (Secure Coding Standards).', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-3'),
  ('ECC', '1-6-3-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-3-2', 'استخدام مصادر مرخصة وموثوقة لأدوات تطوير التطبيقات والمكتبات الخاصة بها (Libraries).', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-3'),
  ('ECC', '1-6-3-3', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-3-3', 'إجراء اختبار للتحقق من مدى استيفاء التطبيقات للمتطلبات الأمنية السيبرانية للجهة.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-3'),
  ('ECC', '1-6-3-4', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-6-3-4', 'أمن التكامل (Integration) بين التطبيقات.', 'حوكمة الأمن السيبراني', 'sub_control', '16', NULL, '1-6-3'),
