  ('ECC', '1-7-2', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني - 1-7-2', 'في حال وجود اتفاقيات دولية أو التزامات معتمدة محلياً تتضمن متطلبات خاصة بالأمن السيبراني، فيجب على الجهة الالتزام بتلك المتطلبات.', 'حوكمة الأمن السيبراني', 'control', '17', NULL, NULL),
