  ('ECC', '1-8-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-8-2', 'يجب مراجعة وتدقيق تطبيق ضوابط الأمن السيبراني في الجهة، من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني في الجهة (مثل الإدارة المعنية بالمراجعة في الجهة). على أن تتم المراجعة والتدقيق بشكل مستقل يراعى فيه مبدأ عدم تعارض المصالح، وذلك وفقاً للمعايير العامة المقبولة للمراجعة والتدقيق والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'حوكمة الأمن السيبراني', 'control', '17', NULL, NULL),
  ('ECC', '1-8-3', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-8-3', 'يجب توثيق نتائج مراجعة وتدقيق الأمن السيبراني، وعرضها على اللجنة الإشرافية للأمن السيبراني وصاحب الصلاحية. كما يجب أن تشتمل النتائج على نطاق المراجعة والتدقيق، والملاحظات المكتشفة، والتوصيات والإجراءات التصحيحية، وخطة معالجة الملاحظات.', 'حوكمة الأمن السيبراني', 'control', '17', NULL, NULL),
