  ('ECC', '2-14-1', 'الأمن المادي - 2-14-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'تعزيز الأمن السيبراني', 'control', '23-24', NULL, NULL),
  ('ECC', '2-14-2', 'الأمن المادي - 2-14-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'تعزيز الأمن السيبراني', 'control', '23-24', NULL, NULL),
  ('ECC', '2-14-3', 'الأمن المادي - 2-14-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '23-24', NULL, NULL),
  ('ECC', '2-14-3-1', 'الأمن المادي - 2-14-3-1', 'الدخول المصرح به للأماكن الحساسة في الجهة (مثل: مركز بيانات الجهة، مركز التعافي من الكوارث، أماكن معالجة المعلومات الحساسة، مركز المراقبة الأمنية، غرف اتصالات الشبكة، مناطق الإمداد الخاصة بالأجهزة والعتاد التقنية، وغيرها).', 'تعزيز الأمن السيبراني', 'sub_control', '23-24', NULL, '2-14-3'),
  ('ECC', '2-14-3-2', 'الأمن المادي - 2-14-3-2', 'سجلات الدخول والمراقبة (CCTV).', 'تعزيز الأمن السيبراني', 'sub_control', '23-24', NULL, '2-14-3'),
  ('ECC', '2-14-3-3', 'الأمن المادي - 2-14-3-3', 'حماية معلومات سجلات الدخول والمراقبة.', 'تعزيز الأمن السيبراني', 'sub_control', '23-24', NULL, '2-14-3'),
  ('ECC', '2-14-3-4', 'الأمن المادي - 2-14-3-4', 'أمن إتلاف وإعادة استخدام الأصول المادية التي تحوي معلومات مصنفة (وتشمل: الوثائق الورقية ووسائط الحفظ والتخزين).', 'تعزيز الأمن السيبراني', 'sub_control', '23-24', NULL, '2-14-3'),
  ('ECC', '2-14-3-5', 'الأمن المادي - 2-14-3-5', 'أمن الأجهزة والمعدات داخل مباني الجهة وخارجها.', 'تعزيز الأمن السيبراني', 'sub_control', '23-24', NULL, '2-14-3'),
  ('ECC', '2-14-4', 'الأمن المادي - 2-14-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب دورياً.', 'تعزيز الأمن السيبراني', 'control', '23-24', NULL, NULL),
  ('ECC', '2-15-1', 'حماية تطبيقات الويب - 2-15-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'تعزيز الأمن السيبراني', 'control', '24', NULL, NULL),
  ('ECC', '2-15-2', 'حماية تطبيقات الويب - 2-15-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة.', 'تعزيز الأمن السيبراني', 'control', '24', NULL, NULL),
  ('ECC', '2-15-3', 'حماية تطبيقات الويب - 2-15-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '24', NULL, NULL),
  ('ECC', '2-15-3-1', 'حماية تطبيقات الويب - 2-15-3-1', 'استخدام جدار الحماية لتطبيقات الويب (Web Application Firewall).', 'تعزيز الأمن السيبراني', 'sub_control', '24', NULL, '2-15-3'),
  ('ECC', '2-15-3-2', 'حماية تطبيقات الويب - 2-15-3-2', 'استخدام مبدأ المعمارية متعددة المستويات (Multi-tier Architecture).', 'تعزيز الأمن السيبراني', 'sub_control', '24', NULL, '2-15-3'),
  ('ECC', '2-15-3-3', 'حماية تطبيقات الويب - 2-15-3-3', 'استخدام بروتوكولات آمنة (مثل بروتوكول HTTPS).', 'تعزيز الأمن السيبراني', 'sub_control', '24', NULL, '2-15-3'),
  ('ECC', '2-15-3-4', 'حماية تطبيقات الويب - 2-15-3-4', 'توضيح سياسة الاستخدام الآمن للمستخدمين.', 'تعزيز الأمن السيبراني', 'sub_control', '24', NULL, '2-15-3'),
  ('ECC', '2-15-3-5', 'حماية تطبيقات الويب - 2-15-3-5', 'التحقق من الهوية على أن يتم تحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات دخول المستخدمين.', 'تعزيز الأمن السيبراني', 'sub_control', '24', NULL, '2-15-3'),
  ('ECC', '2-15-4', 'حماية تطبيقات الويب - 2-15-4', 'يجب مراجعة متطلبات الأمن السيبراني لحماية تطبيقات الويب للجهة من المخاطر السيبرانية دورياً.', 'تعزيز الأمن السيبراني', 'control', '24', NULL, NULL),
  ('ECC', '2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('ECC', '2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('ECC', '2-2-3', 'إدارة هويات الدخول والصلاحيات - 2-2-3', 'يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات في الجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('ECC', '2-2-3-1', 'إدارة هويات الدخول والصلاحيات - 2-2-3-1', 'التحقق من الهوية أحادي العنصر (Single-factor authentication) بناءً على إدارة تسجيل المستخدم، وإدارة كلمة المرور.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-2-3'),
  ('ECC', '2-2-3-2', 'إدارة هويات الدخول والصلاحيات - 2-2-3-2', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناءً على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات الدخول عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-2-3'),
  ('ECC', '2-2-3-3', 'إدارة هويات الدخول والصلاحيات - 2-2-3-3', 'إدارة تصاريح وصلاحيات المستخدمين بناءً على مبادئ التحكم بالدخول والصلاحيات (Authorization) (مبدأ الحاجة إلى المعرفة والاستخدام "Need-to-know and Need-to-use"، ومبدأ الحد الأدنى من الصلاحيات والامتيازات "Least Privilege"، ومبدأ فصل المهام "Segregation of Duties").', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-2-3'),
  ('ECC', '2-2-3-4', 'إدارة هويات الدخول والصلاحيات - 2-2-3-4', 'إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-2-3'),
  ('ECC', '2-2-3-5', 'إدارة هويات الدخول والصلاحيات - 2-2-3-5', 'المراجعة الدورية لهويات الدخول والصلاحيات.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-2-3'),
  ('ECC', '2-2-4', 'إدارة هويات الدخول والصلاحيات - 2-2-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('ECC', '2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', 'تعزيز الأمن السيبراني', 'control', '19-20', NULL, NULL),
  ('ECC', '2-3-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', 'تعزيز الأمن السيبراني', 'control', '19-20', NULL, NULL),
  ('ECC', '2-3-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19-20', NULL, NULL),
  ('ECC', '2-3-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-3-1', 'الحماية من الفيروسات والبرامج والأنشطة المشبوهة والبرمجيات الضارة (Malware) على أجهزة المستخدمين والخوادم باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة، وإدارتها بشكل آمن.', 'تعزيز الأمن السيبراني', 'sub_control', '19-20', NULL, '2-3-3'),
  ('ECC', '2-3-3-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-3-2', 'التقييد الحازم لاستخدام أجهزة ووسائط التخزين الخارجية والأمن المتعلق بها.', 'تعزيز الأمن السيبراني', 'sub_control', '19-20', NULL, '2-3-3'),
  ('ECC', '2-3-3-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-3-3', 'إدارة حزم التحديثات والإصلاحات للأنظمة والتطبيقات والأجهزة (Patch Management).', 'تعزيز الأمن السيبراني', 'sub_control', '19-20', NULL, '2-3-3'),
  ('ECC', '2-3-3-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-3-4', 'مزامنة التوقيت (Clock Synchronization) مركزياً ومن مصدر دقيق وموثوق، ومن هذه المصادر ما توفره الهيئة السعودية للمواصفات والمقاييس والجودة.', 'تعزيز الأمن السيبراني', 'sub_control', '19-20', NULL, '2-3-3'),
  ('ECC', '2-3-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-4', 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '19-20', NULL, NULL),
  ('ECC', '2-4-1', 'حماية البريد الإلكتروني - 2-4-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('ECC', '2-4-2', 'حماية البريد الإلكتروني - 2-4-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('ECC', '2-4-3', 'حماية البريد الإلكتروني - 2-4-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('ECC', '2-4-3-1', 'حماية البريد الإلكتروني - 2-4-3-1', 'تحليل وتصفية (Filtering) رسائل البريد الإلكتروني (وخصوصاً رسائل التصيد الإلكتروني "Phishing Emails" والرسائل الإقتحامية "Spam Emails") باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة للبريد الإلكتروني.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-4-3'),
  ('ECC', '2-4-3-2', 'حماية البريد الإلكتروني - 2-4-3-2', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك للدخول عن بعد والدخول من خلال صفحة موقع البريد الإلكتروني (Webmail).', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-4-3'),
  ('ECC', '2-4-3-3', 'حماية البريد الإلكتروني - 2-4-3-3', 'النسخ الاحتياطي والأرشفة للبريد الإلكتروني.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-4-3'),
  ('ECC', '2-4-3-4', 'حماية البريد الإلكتروني - 2-4-3-4', 'الحماية من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-4-3'),
  ('ECC', '2-4-3-5', 'حماية البريد الإلكتروني - 2-4-3-5', 'توثيق مجال البريد الإلكتروني للجهة من خلال منصة حصين باستخدام إطار سياسة المرسل (Sender Policy Framework "SPF")، والبريد المعرف بمفاتيح النطاق (Domain Keys Identified Mail "DKIM") وسياسة مصادقة الرسائل والإبلاغ عنها (Domain Message Authentication Reporting and Conformance "DMARC").', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-4-3'),
  ('ECC', '2-4-4', 'حماية البريد الإلكتروني - 2-4-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة بحماية البريد الإلكتروني للجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('ECC', '2-5-1', 'إدارة أمن الشبكات - 2-5-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', 'تعزيز الأمن السيبراني', 'control', '20-21', NULL, NULL),
  ('ECC', '2-5-2', 'إدارة أمن الشبكات - 2-5-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', 'تعزيز الأمن السيبراني', 'control', '20-21', NULL, NULL),
  ('ECC', '2-5-3', 'إدارة أمن الشبكات - 2-5-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '20-21', NULL, NULL),
  ('ECC', '2-5-3-1', 'إدارة أمن الشبكات - 2-5-3-1', 'العزل والتقسيم المادي أو المنطقي لأجزاء الشبكات بشكل آمن، واللازم للسيطرة على مخاطر الأمن السيبراني ذات العلاقة، باستخدام جدار الحماية (Firewall) ومبدأ الدفاع الأمني متعدد المراحل (Defense-in-Depth).', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-2', 'إدارة أمن الشبكات - 2-5-3-2', 'عزل شبكة بيئة الإنتاج عن شبكات بيئات التطوير والاختبار.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-3', 'إدارة أمن الشبكات - 2-5-3-3', 'أمن التصفح والاتصال بالإنترنت، ويشمل ذلك التقييد الحازم للمواقع الإلكترونية المشبوهة، ومواقع مشاركة وتخزين الملفات، ومواقع الدخول عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-4', 'إدارة أمن الشبكات - 2-5-3-4', 'أمن الشبكات اللاسلكية وحمايتها باستخدام وسائل آمنة للتحقق من الهوية والتشفير، وعدم ربط الشبكات اللاسلكية بشبكة الجهة الداخلية إلا بناءً على دراسة متكاملة للمخاطر المترتبة على ذلك والتعامل معها بما يضمن حماية الأصول التقنية للجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-5', 'إدارة أمن الشبكات - 2-5-3-5', 'قيود وإدارة منافذ وبروتوكولات وخدمات الشبكة.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-6', 'إدارة أمن الشبكات - 2-5-3-6', 'أنظمة الحماية المتقدمة لاكتشاف ومنع الاختراقات (Intrusion Prevention Systems).', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-7', 'إدارة أمن الشبكات - 2-5-3-7', 'أمن نظام أسماء النطاقات (DNS).', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-8', 'إدارة أمن الشبكات - 2-5-3-8', 'حماية قناة تصفح الإنترنت من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-3-9', 'إدارة أمن الشبكات - 2-5-3-9', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack "DDoS") للحد من المخاطر الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني', 'sub_control', '20-21', NULL, '2-5-3'),
  ('ECC', '2-5-4', 'إدارة أمن الشبكات - 2-5-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '20-21', NULL, NULL),
  ('ECC', '2-6-1', 'أمن الأجهزة المحمولة - 2-6-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة والأجهزة الشخصية للعاملين (BYOD) عند ارتباطها بشبكة الجهة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-6-2', 'أمن الأجهزة المحمولة - 2-6-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-6-3', 'أمن الأجهزة المحمولة - 2-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-6-3-1', 'أمن الأجهزة المحمولة - 2-6-3-1', 'فصل وتشفير البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD).', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-6-3'),
