  ('ECC', '2-6-4', 'أمن الأجهزة المحمولة - 2-6-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة لأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-7-1', 'حماية البيانات والمعلومات - 2-7-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-7-2', 'حماية البيانات والمعلومات - 2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('ECC', '2-7-3', 'حماية البيانات والمعلومات - 2-7-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة بحد أدنى المتطلبات المذكورة في ضوابط الأمن السيبراني للبيانات الصادرة من الهيئة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
