  ('ECC', '2-8-2', 'التشفير - 2-8-2', 'يجب تطبيق متطلبات الأمن السيبراني للتشفير في الجهة.', 'تعزيز الأمن السيبراني', 'control', '21-22', NULL, NULL),
  ('ECC', '2-8-3', 'التشفير - 2-8-3', 'يجب أن تغطي متطلبات الأمن السيبراني للتشفير بحد أدنى المتطلبات المذكورة في المعايير الوطنية للتشفير الصادرة من الهيئة، مع تطبيق مستوى التشفير المناسب، وذلك بحسب طبيعة ومستوى حساسية البيانات والشبكات والأنظمة وبناءً على تقييم المخاطر من قبل الجهة وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة، وفقاً لما يلي:', 'تعزيز الأمن السيبراني', 'control', '21-22', NULL, NULL),
  ('ECC', '2-8-3-1', 'التشفير - 2-8-3-1', 'معايير أنظمة وحلول التشفير المعتمدة والقيود المطبقة عليها (تقنياً وتنظيمياً).', 'تعزيز الأمن السيبراني', 'sub_control', '21-22', NULL, '2-8-3'),
  ('ECC', '2-8-3-2', 'التشفير - 2-8-3-2', 'الإدارة الآمنة لمفاتيح التشفير خلال عمليات دورة حياتها.', 'تعزيز الأمن السيبراني', 'sub_control', '21-22', NULL, '2-8-3'),
  ('ECC', '2-8-3-3', 'التشفير - 2-8-3-3', 'تشفير البيانات أثناء النقل والتخزين والمعالجة بناءً على تصنيفها وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني', 'sub_control', '21-22', NULL, '2-8-3'),
