  ('ECC', '2-9-1', 'إدارة النسخ الاحتياطية - 2-9-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('ECC', '2-9-2', 'إدارة النسخ الاحتياطية - 2-9-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
