  ('ECC', '2-9-3-2', 'إدارة النسخ الاحتياطية - 2-9-3-2', 'القدرة السريعة على استعادة البيانات والأنظمة بعد التعرض لحوادث الأمن السيبراني.', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-9-3'),
