  ('ECC', '2-9-4', 'إدارة النسخ الاحتياطية - 2-9-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('ECC', '3-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة.', 'صمود الأمن السيبراني', 'control', '25', NULL, NULL),
  ('ECC', '3-1-2', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-2', 'يجب تطبيق متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة.', 'صمود الأمن السيبراني', 'control', '25', NULL, NULL),
  ('ECC', '3-1-3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-3', 'يجب أن تغطي إدارة استمرارية الأعمال في الجهة بحد أدنى ما يلي:', 'صمود الأمن السيبراني', 'control', '25', NULL, NULL),
  ('ECC', '3-1-3-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-3-1', 'التأكد من استمرارية الأنظمة والإجراءات المتعلقة بالأمن السيبراني.', 'صمود الأمن السيبراني', 'sub_control', '25', NULL, '3-1-3'),
  ('ECC', '3-1-3-2', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-3-2', 'وضع خطط الاستجابة لحوادث الأمن السيبراني التي قد تؤثر على استمرارية أعمال الجهة.', 'صمود الأمن السيبراني', 'sub_control', '25', NULL, '3-1-3'),
  ('ECC', '3-1-3-3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-3-3', 'وضع خطط التعافي من الكوارث (Disaster Recovery Plan).', 'صمود الأمن السيبراني', 'sub_control', '25', NULL, '3-1-3'),
  ('ECC', '3-1-4', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-4', 'يجب مراجعة متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة دورياً.', 'صمود الأمن السيبراني', 'control', '25', NULL, NULL),
  ('ECC', '4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني ضمن العقود والاتفاقيات مع الأطراف الخارجية للجهة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-2', 'يجب أن تغطي متطلبات الأمن السيبراني ضمن العقود والاتفاقيات (مثل اتفاقية مستوى الخدمة SLA) مع الأطراف الخارجية التي قد تتأثر بإصابتها بيانات الجهة أو الخدمات المقدمة لها بحد أدنى ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-2-1', 'بنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) والحذف الآمن من قبَل الطرف الخارجي لبيانات الجهة عند انتهاء الخدمة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-1-2'),
  ('ECC', '4-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-2-2', 'إجراءات التواصل في حال حدوث حادثة أمن سيبراني.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-1-2'),
  ('ECC', '4-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-2-3', 'إلزام الطرف الخارجي بتطبيق متطلبات وسياسات الأمن السيبراني للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-1-2'),
  ('ECC', '4-1-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-3', 'يجب أن تغطي متطلبات الأمن السيبراني مع الأطراف الخارجية التي تقدم خدمات إسناد لتقنية المعلومات، أو خدمات مدارة بحد أدنى ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-1-3-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-3-1', 'إجراء تقييم لمخاطر الأمن السيبراني، والتأكد من وجود ما يضمن السيطرة على تلك المخاطر، قبل توقيع العقود والاتفاقيات أو عند تغيير المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-1-3'),
  ('ECC', '4-1-3-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-3-2', 'أن تكون مراكز عمليات خدمات الأمن السيبراني المدارة للتشغيل والمراقبة، والتي تستخدم طريقة الوصول عن بعد، موجودة بالكامل داخل المملكة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-1-3'),
  ('ECC', '4-1-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-4', 'يجب مراجعة متطلبات الأمن السيبراني مع الأطراف الخارجية دورياً.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-2-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-2-2', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة للجهة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-2-3', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-3', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط ضمن المكونات الرئيسية رقم (1) و(2) و(3) والمكون الفرعي رقم (4-1) الضرورية لحماية بيانات الجهة أو الخدمات المقدمة لها، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة بحد أدنى ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('ECC', '4-2-3-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-3-1', 'تصنيف البيانات قبل استضافتها لدى مقدمي خدمات الحوسبة السحابية والاستضافة، وإعادتها للجهة (بصيغة قابلة للاستخدام) عند انتهاء الخدمة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-2-3'),
  ('ECC', '4-2-3-2', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-3-2', 'فصل البيئة الخاصة بالجهة (وخصوصاً الخوادم الافتراضية) عن غيرها من البيئات التابعة لجهات أخرى في خدمات الحوسبة السحابية.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '26', NULL, '4-2-3'),
  ('ECC', '4-2-4', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-4', 'يجب مراجعة متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة دورياً.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '26', NULL, NULL),
  ('DCC', '1-1-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-1', 'رجوعاً للضابط 1-8-1 في الضوابط الأساسية للأمن السيبراني، فإنه يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني للبيانات حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني', 'control', '11', NULL, NULL),
  ('DCC', '1-1-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-2', 'رجوعاً للضابط 1-8-2 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن تتم مراجعة تطبيق ضوابط الأمن السيبراني للبيانات من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني من داخل الجهة حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني', 'control', '11', NULL, NULL),
  ('DCC', '1-2-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-9-1 في الضوابط الأساسية للأمن السيبراني يجب أن تغطي متطلبات الأمن السيبراني المتعلق بالموارد البشرية في الجهة بحد أدنى ما يلي خلال وبعد إنتهاء/إنهاء العلاقة الوظيفية في الجهة:', 'حوكمة الأمن السيبراني', 'control', '11', NULL, NULL),
  ('DCC', '1-2-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1-1', 'إجراء المسح الأمني (Screening and vetting) للعاملين في الوظائف ذات العلاقة بالتعامل مع البيانات.', 'حوكمة الأمن السيبراني', 'sub_control', '11', NULL, '1-2-1'),
  ('DCC', '1-2-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1-2', 'تعهد العاملين في الجهة بعدم استخدام تطبيقات التراسل أو التواصل الإجتماعي أو خدمات التخزين السحابية الشخصية لإنشاء أو تخزين أو مشاركة البيانات الخاصة بالجهة، باستثناء تطبيقات التراسل الآمنة المعتمدة من الجهات ذات العلاقة.', 'حوكمة الأمن السيبراني', 'sub_control', '11', NULL, '1-2-1'),
  ('DCC', '1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-10-1 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المحاور المتعلقة بحماية البيانات، بما في ذلك:', 'حوكمة الأمن السيبراني', 'control', '11-12', NULL, NULL),
  ('DCC', '1-3-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-1', 'مخاطر التسريب والوصول غير المصرح به للبيانات خلال دورة حياتها.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-2', 'التعامل الآمن مع البيانات المصنفة خلال السفر والتواجد خارج مكان العمل.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-3', 'التعامل الآمن مع البيانات خلال الاجتماعات (الافتراضية والحضورية).', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-4', 'الاستخدام الآمن للطابعات والماسحات الضوئية وآلات التصوير.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-5', 'إجراءات الإتلاف الآمن للبيانات.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-6', 'مخاطر مشاركة الوثائق والمعلومات من خلال قنوات تواصل غير مؤمنة.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '1-3-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-7', 'المخاطر السيبرانية المتعلقة باستخدام وسائط التخزين الخارجية.', 'حوكمة الأمن السيبراني', 'sub_control', '11-12', NULL, '1-3-1'),
  ('DCC', '2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-2-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '13', NULL, NULL),
  ('DCC', '2-1-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1-1', 'التقييد الحازم بالسماح للحد الأدنى من العاملين للوصول والاطلاع ومشاركة البيانات بناءً على قوائم صلاحيات مقتصرة على موظفين سعوديين إلا بموجب استثناء من قبل صاحب الصلاحية (رئيس الجهة أو من يفوضه) وعلى أن يتم إعتماد هذه القوائم من قبل صاحب الصلاحية.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-1-1'),
  ('DCC', '2-1-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-1-2', 'منع مشاركة قوائم الصلاحيات المعتمدة مع الأشخاص غير المصرح لهم.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-1-1'),
  ('DCC', '2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-2', 'إدارة هويات الدخول وصلاحيات الاطلاع على البيانات باستخدام أنظمة إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', 'تعزيز الأمن السيبراني', 'control', '13', NULL, NULL),
  ('DCC', '2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-1-3', 'بالإضافة للضابط الفرعي 5-3-2-2 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة قوائم الصلاحيات المعتمدة والصلاحيات المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'control', '13', NULL, NULL),
  ('DCC', '2-2-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (Information System and Information Processing Facilities Protection) — pdf p.13 onward - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-3-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '13', NULL, NULL),
  ('DCC', '2-2-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (Information System and Information Processing Facilities Protection) — pdf p.13 onward - 2-2-1-1', 'تطبيق حزم التحديثات والإصلاحات الأمنية من وقت إطلاقها للأنظمة المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-2-1'),
  ('DCC', '2-2-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات (Information System and Information Processing Facilities Protection) — pdf p.13 onward - 2-2-1-2', 'مراجعة إعدادات الحماية والتحصين للأنظمة المستخدمة للتعامل مع البيانات (Security Configuration and Hardening) حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-2-1'),
  ('DCC', '2-2-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات (Information System and Information Processing Facilities Protection) — pdf p.13 onward - 2-2-1-3', 'مراجعة وتحصين الإعدادات المصنعية (مثل كلمات المرور الثابتة، والخلفية الافتراضية) للأصول التقنية المستخدمة للتعامل مع البيانات.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-2-1'),
  ('DCC', '2-2-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات (Information System and Information Processing Facilities Protection) — pdf p.13 onward - 2-2-1-4', 'تعطيل خاصية تصوير الشاشة (Print Screen or Screen Capture) للأجهزة التي تنشئ أو تعالج الوثائق.', 'تعزيز الأمن السيبراني', 'sub_control', '13', NULL, '2-2-1'),
  ('DCC', '2-3-1', 'أمن الأجهزة المحمولة - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-6-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '14', NULL, NULL),
  ('DCC', '2-3-1-1', 'أمن الأجهزة المحمولة - 2-3-1-1', 'إدارة الأجهزة المحمولة المملوكة للجهة مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-3-1'),
  ('DCC', '2-3-1-2', 'أمن الأجهزة المحمولة - 2-3-1-2', 'إدارة أجهزة (BYOD) مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-3-1'),
  ('DCC', '2-4-1', 'حماية البيانات والمعلومات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-7-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بحماية البيانات والمعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '14', NULL, NULL),
  ('DCC', '2-4-1-1', 'حماية البيانات والمعلومات - 2-4-1-1', 'استخدام خاصية العلامات المائية لترميز كامل الوثيقة عند الإنشاء والتخزين والطباعة وعلى الشاشة وعلى كل نسخة بحيث يكون الرمز ممكن تتبعه على مستوى المستخدم أو الجهاز.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-4-1'),
  ('DCC', '2-4-1-2', 'حماية البيانات والمعلومات - 2-4-1-2', 'استخدام تقنيات منع تسريب البيانات (Data Leakage Prevention) وتقنيات إدارة الصلاحيات (Rights Management).', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-4-1'),
  ('DCC', '2-4-1-3', 'حماية البيانات والمعلومات - 2-4-1-3', 'حظر استخدام البيانات في أي بيئة غير بيئة الإنتاج (Production Environment) إلا بعد إجراء تقييم للمخاطر وتطبيق ضوابط لحماية تلك البيانات، مثل تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-4-1'),
  ('DCC', '2-4-1-4', 'حماية البيانات والمعلومات - 2-4-1-4', 'استخدام خدمة حماية العلامة التجارية لحماية هوية الجهة من الانتحال (Brand Protection).', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-4-1'),
  ('DCC', '2-5-1', 'التشفير - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-8-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات التشفير للأمن السيبراني في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-5-1-1', 'التشفير - 2-5-1-1', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير عند الإنشاء والتخزين والمشاركة وعلى كامل الاتصال الشبكي المستخدم لنقل البيانات وفقًا للمستوى المتقدم (Advanced) ضمن المعايير الوطنية للتشفير (NCS – 1:2020).', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-5-1'),
  ('DCC', '2-5-1-2', 'التشفير - 2-5-1-2', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير عند الإنشاء والتخزين والمشاركة وعلى كامل الاتصال الشبكي المستخدم لنقل البيانات وفقًا للمستوى الأساسي (Moderate) ضمن المعايير الوطنية للتشفير (NCS – 1:2020).', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-5-1'),
  ('DCC', '2-6-1', 'الإتلاف الآمن للبيانات - 2-6-1', 'يجب أن تغطي متطلبات الإتلاف الآمن للبيانات في الجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-6-1-1', 'الإتلاف الآمن للبيانات - 2-6-1-1', 'تحديد التقنيات والأدوات والإجراءات لتنفيذ عمليات الإتلاف الآمن للبيانات حسب مستوى تصنيف البيانات.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-6-1'),
  ('DCC', '2-6-1-2', 'الإتلاف الآمن للبيانات - 2-6-1-2', 'عند انتهاء الحاجة لاستخدام وسائط التخزين بشكل نهائي، يجب أن يتم الإتلاف الآمن (Secure Disposal) لوسائط التخزين وذلك باستخدام التقنيات والأدوات وإتّباع الإجراءات التي تم تحديدها في الضابط رقم 2-6-1-1.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-6-1'),
  ('DCC', '2-6-1-3', 'الإتلاف الآمن للبيانات - 2-6-1-3', 'عند الحاجة لإعادة استخدام وسائط التخزين، يجب أن يتم الحذف الآمن للبيانات (Secure Erasure)، بحيث لا يمكن استرجاعها.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-6-1'),
  ('DCC', '2-6-1-4', 'الإتلاف الآمن للبيانات - 2-6-1-4', 'يجب أن يتم التحقق من تنفيذ عمليات الإتلاف أو الحذف الآمن للبيانات المشار إليها في الضابطين رقم 2-6-1-2 و2-6-1-3.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-6-1'),
  ('DCC', '2-6-1-5', 'الإتلاف الآمن للبيانات - 2-6-1-5', 'الاحتفاظ بسجل لعمليات الإتلاف والحذف الآمن للبيانات التي تم تنفيذها.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-6-1'),
  ('DCC', '2-6-2', 'الإتلاف الآمن للبيانات - 2-6-2', 'يجب مراجعة تطبيق متطلبات الإتلاف الآمن للبيانات في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-7-1', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-7-2', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-7-3', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3', 'يجب أن تغطي متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '2-7-3-1', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3-1', 'تعطيل خاصية التخزين المؤقت.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-7-3'),
  ('DCC', '2-7-3-2', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3-2', 'تفعيل خاصية التحقق من الهوية في الطابعات والماسحات الضوئية والآلات التصوير المركزية قبل بدء عمليات الطباعة والتصوير والمسح الضوئي.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-7-3'),
  ('DCC', '2-7-3-3', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3-3', 'الاحتفاظ بطريقة آمنة بسجل الكتروني للعمليات الخاصة باستخدام الطابعات والماسحات الضوئية والآت التصوير، لفترة لا تقل عن 12 شهرًا.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-7-3'),
  ('DCC', '2-7-3-4', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3-4', 'تفعيل وحماية سجلات المراقبة لأنظمة CCTV على مواقع أجهزة الطباعة المركزية والماسحات الضوئية والآت التصوير.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-7-3'),
  ('DCC', '2-7-3-5', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-3-5', 'استخدام أجهزة تمزيق الوثائق الورقية (Cross Shredding)، لإتلاف الوثائق في حال الانتهاء من استخدامها نهائيًا.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-7-3'),
  ('DCC', '2-7-4', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير (Cybersecurity for Printers, Scanners and Copy Machines) — pdf p.15 onward - 2-7-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('DCC', '3-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-4 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني المتعلقة بالأطراف الخارجية، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '15', NULL, NULL),
  ('DCC', '3-1-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-1', 'إجراء المسح الأمني (Screening or Vetting) لموظفي الأطراف الخارجية الذين لديهم صلاحيات الاطلاع على البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-2', 'وجود ضمانات تعاقدية للقدرة على حذف بيانات الجهة بطرق آمنة لدى الطرف الخارجي عند الانتهاء/إنهاء العلاقة التعاقدية مع تقديم الأدلة على ذلك.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-1-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-3', 'توثيق كافة عمليات مشاركة البيانات مع الأطراف الخارجية، على أن يشمل ذلك مبررات مشاركة البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-1-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-4', 'عند مشاركة البيانات خارج المملكة يجب التحقق من قدرة الجهة المستضيفة على حماية تلك البيانات والحصول على موافقة صاحب الصلاحية بالإضافة بالالتزام بالمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-1-5', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-5', 'إلزام الأطراف الخارجية بإبلاغ الجهة مباشرةً عند حدوث حادثة أمن سيبراني قد تؤثر على البيانات التي تمت مشاركتها أو إنشائها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-1-6', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-1-6', 'إعادة تصنيف البيانات إلى أقل مستوى يحقق الهدف قبل مشاركتها مع الأطراف الخارجية وذلك باستخدام تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-1'),
  ('DCC', '3-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط الأساسية للأمن السيبراني والضوابط ضمن المكونات الرئيسية رقم (1) و(2) و(3) من هذه الوثيقة، يجب أن تغطي متطلبات الأمن السيبراني عند التعامل مع الجهات الاستشارية للمشاريع الاستراتيجية ذات الحساسية العالية على المستوى الوطني بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '15', NULL, NULL),
  ('DCC', '3-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-1', 'إجراء المسح الأمني (Screening or Vetting) لموظفي شركات الخدمات الاستشارية الذين لديهم صلاحيات الاطلاع على البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-2', 'وجود ضمانات تعاقدية تشمل إلزام موظفي الخدمات الاستشارية بعدم إفشاء المعلومات وكذلك القدرة على حذف بيانات الجهة بطرق آمنة لدى شركات الخدمات الاستشارية عند الانتهاء/إنهاء العلاقة التعاقدية مع تقديم الأدلة على ذلك.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-3', 'توثيق كافة عمليات مشاركة البيانات مع شركات الخدمات الاستشارية، على أن يشمل ذلك مبررات مشاركة البيانات.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-4', 'إلزام شركات الخدمات الاستشارية بإبلاغ الجهة مباشرةً عند حدوث حادثة أمن سيبراني قد تؤثر على البيانات التي تمت مشاركتها أو إنشائها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-5', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-5', 'إعادة تصنيف البيانات إلى أقل مستوى يحقق الهدف، قبل مشاركتها مع شركات الخدمات الاستشارية وذلك باستخدام تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-6', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-6', 'تخصيص قاعة مغلقة لموظفي شركات الخدمات الاستشارية لأداء أعمالهم، مع توفير أجهزة مخصصة مملوكة للجهة من خلالها يتم مشاركة البيانات ومعالجتها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-7', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-7', 'تفعيل أنظمة التحكم بالدخول والخروج من القاعة المغلقة، على أن يكون للمصرح لهم فقط.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('DCC', '3-1-2-8', 'الأمن السيبراني المتعلق بالأطراف الخارجية (Third-Party Cybersecurity) — pdf p.17 onward - 3-1-2-8', 'منع خروج الأجهزة ووحدات التخزين والوثائق من القاعة المغلقة، ومنع إدخال أي أجهزة إلكترونية للقاعة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '15', NULL, '3-1-2'),
  ('CSCC', '1-1-1', 'إستراتيجية الأمن السيبراني - 1-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تضع إستراتيجية الأمن السيبراني للجهة أولوية لدعم حماية الأنظمة الحساسة الخاصة بالجهة.', 'حوكمة الأمن السيبراني', 'control', '14', NULL, NULL),
  ('CSCC', '1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني', 'control', '14', NULL, NULL),
  ('CSCC', '1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تنفيذ إجراء تقييم مخاطر الأمن السيبراني، على الأنظمة الحساسة، مرة واحدة سنوياً على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-2-1'),
  ('CSCC', '1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'إنشاء سجل مخاطر الأمن السيبراني الخاص بالأنظمة الحساسة، ومتابعته مرة شهرياً على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-2-1'),
  ('CSCC', '1-3-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-6-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للأنظمة الحساسة في الجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14-15', NULL, NULL),
  ('CSCC', '1-3-1-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1-1', 'إجراء اختبار التحمل (Stress Testing) للتأكد من سعة المكونات المختلفة.', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-1'),
  ('CSCC', '1-3-1-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1-2', 'التأكد من تطبيق متطلبات استمرارية الأعمال.', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-1'),
  ('CSCC', '1-3-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لمشاريع تطوير التطبيقات، والبرمجيات الخاصة بالأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14-15', NULL, NULL),
  ('CSCC', '1-3-2-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-1', 'إجراء مراجعة أمنية للشفرة المصدرية، قبل إطلاقها (Security Source Code Review).', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-2'),
  ('CSCC', '1-3-2-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-2', 'تأمين الوصول، والتخزين، والتوثيق للشفرة المصدرية (Source Code) وإصداراتها.', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-2'),
  ('CSCC', '1-3-2-3', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-3', 'تأمين واجهة برمجة التطبيقات (Authenticated API).', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-2'),
  ('CSCC', '1-3-2-4', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-4', 'النقل الآمن والموثوق للتطبيقات من بيئات الاختبار (Testing Environment) إلى بيئات الإنتاج (Production Environment) مع حذف أي بيانات، أو هويات، أو كلمات مرور، متعلقة ببيئات الاختبار، قبل النقل.', 'حوكمة الأمن السيبراني', 'sub_control', '14-15', NULL, '1-3-2'),
  ('CSCC', '1-4-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-4-1', 'رجوعاً للضابط 1-8-1 في الضوابط الأساسية للأمن السيبراني، فإنه يجب على الإدارة المعنية بالأمن السيبراني؛ مراجعة تطبيق ضوابط الأمن السيبراني للأنظمة الحساسة، مرة واحدة سنوياً؛ على الأقل.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('CSCC', '1-4-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-4-2', 'رجوعاً للضابط 1-8-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تتم مراجعة تطبيق ضوابط الأمن السيبراني للأنظمة الحساسة؛ من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني من داخل الجهة، مرة واحدة؛ كل ثلاث سنوات على الأقل.', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('CSCC', '1-5-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-9-3 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن تغطي متطلبات الأمن السيبراني، قبل بدء علاقة العاملين المهنية بالجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'control', '15', NULL, NULL),
  ('CSCC', '1-5-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1-1', 'إجراء المسح الأمني (Screening or Vetting) للعاملين على الأنظمة الحساسة.', 'حوكمة الأمن السيبراني', 'sub_control', '15', NULL, '1-5-1'),
  ('CSCC', '1-5-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1-2', 'أن يشغل وظائف الدعم، والتطوير التقني، للأنظمة الحساسة؛ مواطنون ذوو كفاءة عالية.', 'حوكمة الأمن السيبراني', 'sub_control', '15', NULL, '1-5-1'),
  ('CSCC', '2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('CSCC', '2-1-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1-1', 'الاحتفاظ بقائمة محدثة سنوياً، لجميع الأصول التابعة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-1-1'),
  ('CSCC', '2-1-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-1-2', 'تحديد مالك الأصول (Assets Owner)، وإشراكهم في دورة حياة إدارة الأصول التابعة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-1-1'),
  ('CSCC', '2-10-1', 'اختبار الاختراق - 2-10-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-11-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('CSCC', '2-10-1-1', 'اختبار الاختراق - 2-10-1-1', 'نطاق عمل اختبار الاختراق، ليشمل جميع المكونات التقنية للأنظمة الحساسة، وجميع الخدمات المقدمة داخلياً وخارجياً.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-10-1'),
  ('CSCC', '2-10-1-2', 'اختبار الاختراق - 2-10-1-2', 'عمل اختبار الاختراق من قبل فريق مؤهل.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-10-1'),
  ('CSCC', '2-10-2', 'اختبار الاختراق - 2-10-2', 'رجوعاً للضابط 2-11-3-2 في الضوابط الأساسية للأمن السيبراني، يجب عمل اختبار الاختراق على الأنظمة الحساسة، كل ستة أشهر؛ على الأقل.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('CSCC', '2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('CSCC', '2-11-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-1', 'تفعيل سجلات الأحداث (Event logs) الخاصة بالأمن السيبراني؛ على جميع المكونات التقنية للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-11-1'),
  ('CSCC', '2-11-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-2', 'تفعيل التنبيهات وسجلات الأحداث المتعلقة بإدارة تغييرات الملفات (File Integrity Management) ومراقبتها.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-11-1'),
  ('CSCC', '2-11-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-3', 'مراقبة سلوك المستخدم (User Behavior Analytics «UBA») وتحليله.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-11-1'),
  ('CSCC', '2-11-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-4', 'مراقبة سجلات الأحداث، الخاصة بالأنظمة الحساسة على مدار الساعة.', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-11-1'),
  ('CSCC', '2-11-1-5', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-5', 'الاحتفاظ بسجلات الأحداث، الخاصة بالأمن السيبراني، المتعلقة بالأنظمة الحساسة وحمايتها؛ على أن تكون شاملة، ومتضمنة للتفاصيل كاملة (مثل: الوقت، التاريخ، الهوية، النظام المتأثر).', 'تعزيز الأمن السيبراني', 'sub_control', '21', NULL, '2-11-1'),
  ('CSCC', '2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط 2-12-3-5 في الضوابط الأساسية للأمن السيبراني، يجب أن لا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني، على الأنظمة الحساسة عن 18 شهراً؛ حسب المتطلبات التشريعية، والتنظيمية، ذات العلاقة.', 'تعزيز الأمن السيبراني', 'control', '21', NULL, NULL),
  ('CSCC', '2-12-1', 'حماية تطبيقات الويب - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-15-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لحماية تطبيقات الويب الخارجية للأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-12-1-1', 'حماية تطبيقات الويب - 2-12-1-1', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout).', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-12-1'),
  ('CSCC', '2-12-1-2', 'حماية تطبيقات الويب - 2-12-1-2', 'تطبيق معايير أمن التطبيقات وحمايتها (OWASP Top Ten) في حدها الأدنى.', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-12-1'),
  ('CSCC', '2-12-2', 'حماية تطبيقات الويب - 2-12-2', 'رجوعاً للضابط 2-15-3-2 في الضوابط الأساسية للأمن السيبراني، يجب استخدام مبدأ المعمارية ذات المستويات المتعددة (Multi-tier Architecture) على أن لا يقل عدد المستويات عن 3 (3-Tier Architecture).', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-13-1', 'حماية التطبيقات - 2-13-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة من المخاطر السيبرانية.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-13-2', 'حماية التطبيقات - 2-13-2', 'يجب تطبيق متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-13-3', 'حماية التطبيقات - 2-13-3', 'يجب أن تغطي متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-13-3-1', 'حماية التطبيقات - 2-13-3-1', 'استخدام مبدأ المعمارية ذات المستويات المتعددة (Multi-tier Architecture) على أن لا يقل عدد المستويات عن 3 (3-Tier Architecture).', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-13-3'),
  ('CSCC', '2-13-3-2', 'حماية التطبيقات - 2-13-3-2', 'استخدام بروتوكولات آمنة (مثل بروتوكول HTTPS).', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-13-3'),
  ('CSCC', '2-13-3-3', 'حماية التطبيقات - 2-13-3-3', 'توضيح سياسة الاستخدام الآمن للمستخدمين.', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-13-3'),
  ('CSCC', '2-13-3-4', 'حماية التطبيقات - 2-13-3-4', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout).', 'تعزيز الأمن السيبراني', 'sub_control', '22', NULL, '2-13-3'),
  ('CSCC', '2-13-4', 'حماية التطبيقات - 2-13-4', 'مراجعة متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة دورياً.', 'تعزيز الأمن السيبراني', 'control', '22', NULL, NULL),
  ('CSCC', '2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة الحساسة في الجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('CSCC', '2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'منع الدخول عن بعد من خارج المملكة.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'تقييد الدخول عن بعد من داخل المملكة؛ على أن يتم التأكد عن طريق مركز العمليات الأمنية الخاص بالجهة، عند كل عملية دخول؛ ومراقبة الأنشطة المتعلقة بالدخول عن بعد باستمرار.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication «MFA») لجميع المستفيدين.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-4', 'إدارة هويات الدخول والصلاحيات - 2-2-1-4', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication «MFA») للمستخدمين ذوي الصلاحيات الهامة، والحساسة؛ وعلى الأنظمة المستخدمة لإدارة الأنظمة الحساسة المذكورة في الضابط 2-3-1-4 ومتابعتها.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-5', 'إدارة هويات الدخول والصلاحيات - 2-2-1-5', 'وضع سياسة آمنة لكلمة المرور ذات معايير عالية، وتطبيقها.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-6', 'إدارة هويات الدخول والصلاحيات - 2-2-1-6', 'استخدام الطرق والخوارزميات الآمنة لحفظ ومعالجة كلمات المرور مثل: استخدام دوال الاختزال (Hashing Functions).', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-7', 'إدارة هويات الدخول والصلاحيات - 2-2-1-7', 'الإدارة الآمنة لحسابات الخدمات (Service Account) ما بين التطبيقات والأنظمة؛ وتعطيل الدخول البشري التفاعلي (Interactive login) من خلالها؛ فيما عدا مشرفي قواعد البيانات (Database Administrators).', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-1-8', 'إدارة هويات الدخول والصلاحيات - 2-2-1-8', 'منع التعامل المباشر لأي مستخدم مع قواعد البيانات؛ ويتم ذلك من خلال التطبيقات فقط، وبناءً على الصلاحيات المخوّل بها؛ مع مراعاة تطبيق حلول أمنية تحد، أو تمنع من اطلاع مشرفي قواعد البيانات (Database Administrators) على البيانات المصنفة (Classified Data).', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-2-1'),
  ('CSCC', '2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول على الأنظمة الحساسة، مرة واحدة، كل ثلاثة أشهر، على الأقل.', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('CSCC', '2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-3-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة الحساسة، وأجهزة معالجة المعلومات الخاصة بها، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('CSCC', '2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'السماح فقط بقائمة محددة من ملفات التشغيل والبرامج (Whitelisting) للتطبيقات؛ للعمل على الخوادم الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'حماية الخوادم الخاصة بالأنظمة الحساسة بتقنيات حماية الأجهزة الطرفية (End-point Protection) المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'تطبيق حزم التحديثات، والإصلاحات الأمنية، مرة واحدة شهرياً على الأقل، للأنظمة الحساسة الخارجية، والمتصلة بالإنترنت؛ وكل ثلاثة أشهر على الأقل، للأنظمة الحساسة الداخلية؛ مع اتباع آليات التغيير المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'تخصيص أجهزة حاسب (Workstations) للعاملين في الوظائف التقنية، ذات الصلاحيات الهامة والحساسة؛ على أن تكون معزولة في شبكة خاصة، لإدارة الأنظمة (Management Network) وعلى أن لا ترتبط بأي شبكة، أو خدمة أخرى (مثل: خدمة البريد الإلكتروني، الإنترنت).', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-5', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-5', 'تشفير أي وصول إشرافي عبر الشبكة (Non-console Administrative Access) لأي من المكونات التقنية للأنظمة الحساسة، باستخدام خوارزميات، وبروتوكولات التشفير الآمنة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-6', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-6', 'مراجعة إعدادات الأنظمة الحساسة وتحصيناتها (Secure Configuration and Hardening) كل ستة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-7', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-7', 'مراجعة الإعدادات المصنعية (Default Configuration) وتعديلها، والتأكد من عدم وجود كلمات مرور ثابتة، وخلفية، وافتراضية (Hard-Coded, Backdoor and Default Passwords) ما أمكن تطبيقه.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-3-1-8', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-8', 'حماية السجلات، والملفات الحساسة للأنظمة، من الوصول غير المصرح به، أو العبث، أو التغيير، أو الحذف غير المشروع.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-3-1'),
  ('CSCC', '2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-5-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الأنظمة الحساسة للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('CSCC', '2-4-1-1', 'إدارة أمن الشبكات - 2-4-1-1', 'العزل والتقسيم المادي، أو المنطقي، لشبكات الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-2', 'إدارة أمن الشبكات - 2-4-1-2', 'مراجعة إعدادات جدار الحماية (Firewall Rules) وقوائمه؛ كل ستة أشهر، على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-3', 'إدارة أمن الشبكات - 2-4-1-3', 'منع التوصيل المباشر، لأي جهاز بالشبكة المحلية للأنظمة الحساسة؛ إلا بعد الفحص والتأكد من توافر عناصر الحماية المحققة، للمستويات المقبولة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-4', 'إدارة أمن الشبكات - 2-4-1-4', 'منع الأنظمة الحساسة من الاتصال بالشبكة اللاسلكية.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-5', 'إدارة أمن الشبكات - 2-4-1-5', 'الحماية من التهديدات المتقدمة المستمرة على مستوى الشبكة (Network APT).', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-6', 'إدارة أمن الشبكات - 2-4-1-6', 'منع الأنظمة الحساسة من الاتصال بالإنترنت في حال أن كانت تقدم خدمة داخلية للجهة؛ ولا توجد هناك حاجة ضرورية جداً، للدخول على الخدمة من خارج الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-7', 'إدارة أمن الشبكات - 2-4-1-7', 'تقديم خدمات الأنظمة الحساسة، من خلال شبكات مستقلة عن الإنترنت، في حال أن كانت خدمات تلك الأنظمة، موجهة لجهات محدودة؛ وليست للأفراد.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-8', 'إدارة أمن الشبكات - 2-4-1-8', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack «DDoS») للحد من المخاطر الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-4-1-9', 'إدارة أمن الشبكات - 2-4-1-9', 'السماح بقائمة محددة (Whitelisting) فقط، لقوائم جدار الحماية، الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-4-1'),
  ('CSCC', '2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، الخاصة بأمن الأجهزة المحمولة، وأجهزة (BYOD) للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('CSCC', '2-5-1-1', 'أمن الأجهزة المحمولة - 2-5-1-1', 'منع الوصول من الأجهزة المحمولة للأنظمة الحساسة، إلا لفترة مؤقتة فقط؛ وذلك بعد إجراء تقييم المخاطر، وأخذ الموافقات اللازمة من الإدارة المعنية بالأمن السيبراني في الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-5-1'),
  ('CSCC', '2-5-1-2', 'أمن الأجهزة المحمولة - 2-5-1-2', 'تشفير أقراص الأجهزة المحمولة، ذات صلاحية الوصول للأنظمة الحساسة، تشفيراً كاملاً (Full Disk Encryption).', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-5-1'),
  ('CSCC', '2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-7-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات؛ بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('CSCC', '2-6-1-1', 'حماية البيانات والمعلومات - 2-6-1-1', 'عدم استخدام بيانات الأنظمة الحساسة في غير بيئة الإنتاج (Production Environment) إلا بعد استخدام ضوابط مشددة لحماية تلك البيانات مثل: تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-6-1'),
  ('CSCC', '2-6-1-2', 'حماية البيانات والمعلومات - 2-6-1-2', 'تصنيف جميع بيانات الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-6-1'),
  ('CSCC', '2-6-1-3', 'حماية البيانات والمعلومات - 2-6-1-3', 'حماية البيانات المصنفة الخاصة بالأنظمة الحساسة من خلال تقنيات، منع تسريب البيانات (Data Leakage Prevention).', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-6-1'),
  ('CSCC', '2-6-1-4', 'حماية البيانات والمعلومات - 2-6-1-4', 'تحديد مدة الاحتفاظ المطلوبة (Retention Period) لبيانات الأعمال المتعلقة بالأنظمة الحساسة؛ حسب التشريعات ذات العلاقة، ويتم الاحتفاظ بالبيانات المطلوبة فقط، في بيئات الإنتاج للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-6-1'),
  ('CSCC', '2-6-1-5', 'حماية البيانات والمعلومات - 2-6-1-5', 'منع نقل أي من بيانات بيئة الإنتاج الخاصة بالأنظمة الحساسة إلى أي بيئة أخرى.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-6-1'),
  ('CSCC', '2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-8-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('CSCC', '2-7-1-1', 'التشفير - 2-7-1-1', 'تشفير جميع بيانات الأنظمة الحساسة؛ أثناء النقل (Data-In-Transit).', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-7-1'),
  ('CSCC', '2-7-1-2', 'التشفير - 2-7-1-2', 'تشفير جميع بيانات الأنظمة الحساسة؛ أثناء التخزين (Data-At-Rest) على مستوى الملفات، أو قاعدة البيانات، أو على مستوى أعمدة محددة، داخل قاعدة البيانات.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-7-1'),
  ('CSCC', '2-7-1-3', 'التشفير - 2-7-1-3', 'استخدام طرق وخوارزميات ومفاتيح وأجهزة تشفير محدثة وآمنة وفقاً لما تصدره الهيئة بهذا الشأن.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-7-1'),
  ('CSCC', '2-8-1', 'إدارة النسخ الاحتياطية - 2-8-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-9-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('CSCC', '2-8-1-1', 'إدارة النسخ الاحتياطية - 2-8-1-1', 'نطاق عمل النسخ الاحتياطي المتصل، وغير المتصل (Online and Offline Backup) ليشمل جميع الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-8-1'),
  ('CSCC', '2-8-1-2', 'إدارة النسخ الاحتياطية - 2-8-1-2', 'عمل النسخ الاحتياطي على فترات زمنية مخطط لها؛ بناءً على تقييم المخاطر للجهة. وتوصي الهيئة بأن يتم عمل النسخ الاحتياطي، للأنظمة الحساسة، بشكل يومي.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-8-1'),
  ('CSCC', '2-8-1-3', 'إدارة النسخ الاحتياطية - 2-8-1-3', 'تأمين الوصول، والتخزين، والنقل لمحتوى النسخ الاحتياطية للأنظمة الحساسة ووسائطها، وحمايتها من الإتلاف، أو التعديل، أو الاطلاع غير المصرح به.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-8-1'),
  ('CSCC', '2-8-2', 'إدارة النسخ الاحتياطية - 2-8-2', 'رجوعاً للضابط 2-9-3-3 في الضوابط الأساسية للأمن السيبراني، يجب إجراء فحص دوري؛ كل ثلاثة أشهر على الأقل، لتحديد مدى فعالية استعادة النسخ الاحتياطية، الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('CSCC', '2-9-1', 'إدارة الثغرات - 2-9-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-10-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات للأنظمة الحساسة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('CSCC', '2-9-1-1', 'إدارة الثغرات - 2-9-1-1', 'استخدام وسائل وأدوات موثوقة لاكتشاف الثغرات.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-9-1'),
  ('CSCC', '2-9-1-2', 'إدارة الثغرات - 2-9-1-2', 'تقييم الثغرات ومعالجتها (بتنصيب حزم التحديثات والإصلاحات) على المكونات التقنية للأنظمة الحساسة، مرة واحدة شهرياً، على الأقل، للأنظمة الحساسة الخارجية، والمتصلة بالإنترنت؛ وكل ثلاثة أشهر على الأقل، للأنظمة الحساسة الداخلية.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-9-1'),
  ('CSCC', '2-9-1-3', 'إدارة الثغرات - 2-9-1-3', 'معالجة فورية للثغرات الحرجة (Critical Vulnerabilities) المكتشفة حديثاً؛ مع اتباع آليات إدارة التغيير، المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '20', NULL, '2-9-1'),
  ('CSCC', '2-9-2', 'إدارة الثغرات - 2-9-2', 'رجوعاً للضابط 2-10-3-1 في الضوابط الأساسية للأمن السيبراني، يجب فحص الثغرات واكتشافها على المكونات التقنية، للأنظمة الحساسة، مرة واحدة شهرياً؛ على الأقل.', 'تعزيز الأمن السيبراني', 'control', '20', NULL, NULL),
  ('CSCC', '3-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 3-1-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي إدارة استمرارية الأعمال في الجهة، بحد أدنى؛ ما يلي:', 'صمود الأمن السيبراني', 'control', '23', NULL, NULL),
  ('CSCC', '3-1-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-1', 'وضع مركز للتعافي من الكوارث للأنظمة الحساسة.', 'صمود الأمن السيبراني', 'sub_control', '23', NULL, '3-1-1'),
  ('CSCC', '3-1-1-2', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-2', 'إدراج الأنظمة الحساسة؛ ضمن خطط التعافي من الكوارث.', 'صمود الأمن السيبراني', 'sub_control', '23', NULL, '3-1-1'),
  ('CSCC', '3-1-1-3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-3', 'إجراء اختبارات دورية؛ للتأكد من فعالية خطط التعافي، من الكوارث للأنظمة الحساسة، مرة واحدة سنوياً؛ على الأقل.', 'صمود الأمن السيبراني', 'sub_control', '23', NULL, '3-1-1'),
  ('CSCC', '3-1-1-4', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-4', 'توصي الهيئة بإجراء اختبار دوري حي؛ للتعافي من الكوارث (Live DR Test) للأنظمة الحساسة.', 'صمود الأمن السيبراني', 'sub_control', '23', NULL, '3-1-1'),
  ('CSCC', '4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 4-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، المتعلقة بالأطراف الخارجية، بحد أدنى؛ ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '24', NULL, NULL),
  ('CSCC', '4-1-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1-1', 'إجراء المسح الأمني (Screening or Vetting) لشركات خدمات الإسناد، ولموظفي خدمات الإسناد، والخدمات المدارة العاملين على الأنظمة الحساسة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '24', NULL, '4-1-1'),
  ('CSCC', '4-1-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1-2', 'أن تكون خدمات الإسناد، والخدمات المدارة على الأنظمة الحساسة؛ عن طريق شركات، وجهات وطنية؛ وفقاً للمتطلبات التشريعية، والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '24', NULL, '4-1-1'),
  ('CSCC', '4-2-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 4-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة، بحد أدنى؛ ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '24', NULL, NULL),
  ('CSCC', '4-2-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-1-1', 'أن يكون موقع استضافة الأنظمة الحساسة، أو أي جزء من مكوناتها التقنية، داخل الجهة، أو في خدمات الحوسبة السحابية، المقدمة من قبل جهات حكومية، أو شركات وطنية محققة لضوابط الحوسبة السحابية الصادرة من الهيئة مع مراعاة تصنيف البيانات المستضافة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '24', NULL, '4-2-1'),
  ('TCC', '1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1', 'رجوعاً للضابط 1-3-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي سياسات وإجراءات الأمن السيبراني بحد أدنى، ما يلي:', 'حوكمة الأمن السيبراني', 'control', '12', NULL, NULL),
  ('TCC', '1-1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1-1', 'تحديد وتوثيق متطلبات وضوابط الأمن السيبراني للعمل عن بعد ضمن سياسات الأمن السيبراني للجهة.', 'حوكمة الأمن السيبراني', 'sub_control', '12', NULL, '1-1-1'),
  ('TCC', '1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '12', NULL, NULL),
  ('TCC', '1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تقييم مخاطر الأمن السيبراني لأنظمة العمل عن بعد، مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '12', NULL, '1-2-1'),
  ('TCC', '1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'تقييم مخاطر الأمن السيبراني عند التخطيط وقبل السماح بالعمل عن بعد لأي خدمة أو نظام.', 'حوكمة الأمن السيبراني', 'sub_control', '12', NULL, '1-2-1'),
  ('TCC', '1-2-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-1-3', 'تضمين مخاطر الأمن السيبراني الخاصة بأنظمة العمل عن بعد والخدمات والأنظمة المسموح لها بالعمل عن بعد في سجل مخاطر الأمن السيبراني الخاص بالجهة، ومتابعته مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '12', NULL, '1-2-1'),
  ('TCC', '1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-3 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المخاطر والتهديدات السيبرانية للعمل عن بعد والاستخدام الآمن للحد من هذه المخاطر والتهديدات، بما في ذلك:', 'حوكمة الأمن السيبراني', 'control', '13', NULL, NULL),
  ('TCC', '1-3-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-1', 'الاستخدام الآمن للأجهزة المخصصة للعمل عن بعد والمحافظة عليها وحمايتها.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-2', 'التعامل الآمن مع هويات الدخول وكلمات المرور.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-3', 'حماية البيانات التي يتم حفظها على الأجهزة المستخدمة للعمل عن بعد والتعامل معها حسب تصنيفها وإجراءات وسياسات الجهة.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-4', 'التعامل الآمن مع التطبيقات والحلول المستخدمة للعمل عن بعد كالاجتماعات الافتراضية، والتعاون ومشاركة الملفات.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-5', 'التعامل الآمن مع الشبكات المنزلية والتأكد من إعدادات الحماية الخاصة بها.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-6', 'تجنب العمل عن بعد باستخدام أجهزة أو شبكات عامة غير موثوقة أو أثناء التواجد في أماكن عامة.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-7', 'الوصول المادي غير المصرح به والفقدان والسرقة والتخريب للأصول التقنية وأنظمة العمل عن بعد.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-1-8', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-8', 'التواصل مباشرة مع الإدارة المعنية بالأمن السيبراني في الجهة حال الاشتباه بتهديد أمن سيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-3-1'),
  ('TCC', '1-3-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-4 في الضوابط الأساسية للأمن السيبراني، فإنه يجب تدريب العاملين على المهارات التقنية اللازمة لضمان تطبيق متطلبات وممارسات الأمن السيبراني عند التعامل مع أنظمة العمل عن بعد.', 'حوكمة الأمن السيبراني', 'control', '13', NULL, NULL),
  ('TCC', '2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '14', NULL, NULL),
  ('TCC', '2-1-1-1', 'إدارة الأصول - 2-1-1-1', 'تحديد وحصر الأصول المعلوماتية والتقنية لأنظمة العمل عن بعد، وتحديثها مرة واحدة، كل سنة؛ على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-1-1'),
  ('TCC', '2-10-1', 'اختبار الاختراق - 2-10-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-11-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق لأنظمة العمل عن بعد، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('TCC', '2-10-1-1', 'اختبار الاختراق - 2-10-1-1', 'نطاق عمل اختبار الاختراق، ليشمل جميع المكونات التقنية لأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-10-1'),
  ('TCC', '2-10-2', 'اختبار الاختراق - 2-10-2', 'رجوعاً للضابط 2-11-3-2 في الضوابط الأساسية للأمن السيبراني، يجب عمل اختبار الاختراق على أنظمة العمل عن بعد مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('TCC', '2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأصول التقنية وأنظمة العمل عن بعد، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('TCC', '2-11-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-1', 'تفعيل سجلات الأحداث (Event Logs) الخاصة بالأمن السيبراني على الأصول التقنية وأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-11-1'),
  ('TCC', '2-11-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-2', 'مراقبة سلوك مستخدمي أنظمة العمل عن بعد (User Behavior Analytics (UBA)) وتحليله.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-11-1'),
  ('TCC', '2-11-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-3', 'مراقبة سجلات الأحداث، الخاصة بالأصول التقنية وأنظمة العمل عن بعد على مدار الساعة.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-11-1'),
  ('TCC', '2-11-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-4', 'تحديث إجراءات مراقبة الأمن السيبراني على مدار الساعة وتطبيقها، بحيث تشمل مراقبة عمليات الدخول عن بعد، ولا سيما عمليات الدخول عن بعد من خارج المملكة والتحقق من صحتها.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-11-1'),
  ('TCC', '2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط 2-12-3-5 في الضوابط الأساسية للأمن السيبراني، يجب ألا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني لأنظمة العمل عن بعد عن 12 شهراً؛ حسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('TCC', '2-12-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-13-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '19', NULL, NULL),
  ('TCC', '2-12-1-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-1', 'تحديث خطط الاستجابة لحوادث الأمن السيبراني ومعلومات التواصل داخل الجهة بما يتوافق مع حالة العمل عن بعد، وبما يضمن القدرة على التواصل وجاهزية فرق الاستجابة للحوادث.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-12-1'),
  ('TCC', '2-12-1-2', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-2', 'الحصول على المعلومات الاستباقية (Threat Intelligence) ذات العلاقة بأنظمة العمل عن بعد بشكل دوري والتعامل معها.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-12-1'),
  ('TCC', '2-12-1-3', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-3', 'تنفيذ وتطبيق التوصيات والتنبيهات الخاصة بحوادث وتهديدات الأمن السيبراني الصادرة من مشرف القطاع أو الهيئة الوطنية للأمن السيبراني.', 'تعزيز الأمن السيبراني', 'sub_control', '19', NULL, '2-12-1'),
  ('TCC', '2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة المستخدمة في العمل عن بعد في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '14', NULL, NULL),
  ('TCC', '2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'إدارة صلاحيات المستخدمين للعمل عن بعد بناءً على احتياجات العمل، مع مراعاة حساسية الأنظمة ومستوى الصلاحيات، ونوعية الأجهزة المستخدمة من قبل الموظفين للعمل عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-2-1'),
  ('TCC', '2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'تقييد إمكانية الوصول عن بعد لنفس المستخدم من أجهزة حاسبات متعددة في نفس الوقت (Concurrent Logins).', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-2-1'),
  ('TCC', '2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'استخدام معايير آمنة لإدارة الهويات وكلمات المرور المستخدمة في أنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '14', NULL, '2-2-1'),
  ('TCC', '2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط الفرعي 2-2-3-5 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول والصلاحيات المستخدمة للعمل عن بعد، بحد أدنى مرة واحدة كل سنة.', 'تعزيز الأمن السيبراني', 'control', '14', NULL, NULL),
  ('TCC', '2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-3-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية أنظمة العمل عن بعد، وأجهزة المعلومات الخاصة بها، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('TCC', '2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'تطبيق حزم التحديثات، والإصلاحات الأمنية لأنظمة العمل عن بعد، مرة واحدة شهرياً على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-3-1'),
  ('TCC', '2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'مراجعة إعدادات الحماية لأنظمة العمل عن بعد والتحصين (Secure Configuration and Hardening)، مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-3-1'),
  ('TCC', '2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'مراجعة وتحصين الإعدادات المصنعية (Default Configuration) للأصول التقنية لأنظمة العمل عن بعد، ومنها وجود كلمات مرور ثابتة، وخلفية وافتراضية.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-3-1'),
  ('TCC', '2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout).', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-3-1'),
  ('TCC', '2-3-1-5', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-5', 'تقييد تفعيل الخصائص والخدمات في أنظمة العمل عن بعد حسب الحاجة، على أن يتم تحليل المخاطر السيبرانية المحتملة في حال الحاجة لتفعيلها.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-3-1'),
  ('TCC', '2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-5-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة للعمل عن بعد، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('TCC', '2-4-1-1', 'إدارة أمن الشبكات - 2-4-1-1', 'تقييد منافذ وبروتوكولات وخدمات الشبكة المستخدمة لعمليات الدخول عن بعد، وخصوصاً على الأنظمة الداخلية، وفتحها حسب الحاجة.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-4-1'),
  ('TCC', '2-4-1-2', 'إدارة أمن الشبكات - 2-4-1-2', 'مراجعة إعدادات وقوائم جدار الحماية (Firewall Rules) ذات العلاقة بأنظمة العمل عن بعد؛ مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-4-1'),
  ('TCC', '2-4-1-3', 'إدارة أمن الشبكات - 2-4-1-3', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service (DDoS)) على أنظمة العمل عن بعد للحد من المخاطر الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-4-1'),
  ('TCC', '2-4-1-4', 'إدارة أمن الشبكات - 2-4-1-4', 'الحماية من التهديدات المتقدمة المستمرة على مستوى الشبكة لأنظمة العمل عن بعد (Network APT).', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-4-1'),
  ('TCC', '2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة للعمل عن بعد في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('TCC', '2-5-1-1', 'أمن الأجهزة المحمولة - 2-5-1-1', 'إدارة الأجهزة المحمولة وأجهزة (BYOD) مركزياً باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management (MDM)).', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-5-1'),
  ('TCC', '2-5-1-2', 'أمن الأجهزة المحمولة - 2-5-1-2', 'تطبيق حزم التحديثات، والإصلاحات الأمنية للأجهزة المحمولة، مرة واحدة شهرياً، على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-5-1'),
  ('TCC', '2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-7-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات للعمل عن بعد في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('TCC', '2-6-1-1', 'حماية البيانات والمعلومات - 2-6-1-1', 'تحديد البيانات المصنفة، حسب التشريعات ذات العلاقة، التي يمكن استخدامها أو الوصول إليها أو التعامل معها من خلال أنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-6-1'),
  ('TCC', '2-6-1-2', 'حماية البيانات والمعلومات - 2-6-1-2', 'حماية البيانات المصنفة، التي تم تحديدها في الضابط 2-6-1-1، باستخدام ضوابط مثل منع استخدام نوع من البيانات المصنفة أو تقنيات مثل منع تسريب البيانات (Data Leakage Prevention). ويمكن تحديد هذه الضوابط والتقنيات عن طريق تحليل المخاطر السيبرانية للجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-6-1'),
  ('TCC', '2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-8-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بالتشفير لدى المشتركين، بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('TCC', '2-7-1-1', 'التشفير - 2-7-1-1', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير على كامل الاتصال الشبكي المستخدم للعمل عن بعد وفقاً للمستوى المتقدم (Advanced) ضمن المعايير الوطنية للتشفير (NCS – 1:2020).', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-7-1'),
  ('TCC', '2-8-1', 'إدارة النسخ الاحتياطية - 2-8-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-9-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية لأنظمة العمل عن بعد في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('TCC', '2-8-1-1', 'إدارة النسخ الاحتياطية - 2-8-1-1', 'عمل النسخ الاحتياطي على فترات زمنية مخطط لها؛ بناء على تقييم المخاطر للجهة، لأنظمة العمل عن بعد. وتوصي الهيئة بأن يتم عمل النسخ الاحتياطية لأنظمة العمل عن بعد مرة واحدة كل أسبوع.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-8-1'),
  ('TCC', '2-8-2', 'إدارة النسخ الاحتياطية - 2-8-2', 'رجوعاً للضابط 2-9-3-3 في الضوابط الأساسية للأمن السيبراني، يجب إجراء فحص دوري؛ كل ستة أشهر على الأقل، لتحديد مدى فعالية استعادة النسخ الاحتياطية، الخاصة بأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('TCC', '2-9-1', 'إدارة الثغرات - 2-9-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-10-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات للأصول التقنية وأنظمة العمل عن بعد، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('TCC', '2-9-1-1', 'إدارة الثغرات - 2-9-1-1', 'فحص الثغرات واكتشافها على أنظمة العمل عن بعد وتصنيفها حسب خطورتها، مرة واحدة كل ثلاثة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-9-1'),
  ('TCC', '2-9-1-2', 'إدارة الثغرات - 2-9-1-2', 'معالجة الثغرات على أنظمة العمل عن بعد، مرة واحدة كل ثلاثة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-9-1'),
  ('TCC', '3-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 4-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '20', NULL, NULL),
  ('TCC', '3-1-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 3-1-1-1', 'موقع استضافة أنظمة العمل عن بعد يجب أن يكون داخل المملكة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '20', NULL, '3-1-1'),
  ('OSMACC', '1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1', 'رجوعاً للضابط 1-3-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل سياسات وإجراءات الأمن السيبراني ما يأتي:', 'حوكمة الأمن السيبراني', 'control', '13', NULL, NULL),
  ('OSMACC', '1-1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1-1', 'تحديد وتوثيق متطلبات وضوابط الأمن السيبراني لحسابات التواصل الاجتماعي ضمن سياسات الأمن السيبراني للجهة.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-1-1'),
  ('OSMACC', '1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني', 'control', '13', NULL, NULL),
  ('OSMACC', '1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تقييم مخاطر الأمن السيبراني لحسابات التواصل الاجتماعي، مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-2-1'),
  ('OSMACC', '1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'تقييم مخاطر الأمن السيبراني عند التخطيط وقبل السماح باستخدام شبكات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-2-1'),
  ('OSMACC', '1-2-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-1-3', 'تضمين مخاطر الأمن السيبراني الخاصة بحسابات التواصل الاجتماعي والخدمات والأنظمة المستخدمة في ذلك في سجل مخاطر الأمن السيبراني الخاص بالجهة، ومتابعته مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'sub_control', '13', NULL, '1-2-1'),
  ('OSMACC', '1-3-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-9-4 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني المتعلقة بالعاملين المسؤولين عن إدارة حسابات التواصل الاجتماعي للجهة بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني', 'control', '13-14', NULL, NULL),
  ('OSMACC', '1-3-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1-1', 'التوعية بالأمن السيبراني لحسابات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'sub_control', '13-14', NULL, '1-3-1'),
  ('OSMACC', '1-3-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1-2', 'تطبيق متطلبات الأمن السيبراني والالتزام بها وفقاً لسياسات وإجراءات وعمليات الأمن السيبراني لحسابات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'sub_control', '13-14', NULL, '1-3-1'),
  ('OSMACC', '1-4-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-3 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المخاطر والتهديدات السيبرانية لحسابات التواصل الاجتماعي والاستخدام الآمن للحد من هذه المخاطر والتهديدات، بما في ذلك:', 'حوكمة الأمن السيبراني', 'control', '14', NULL, NULL),
  ('OSMACC', '1-4-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-1', 'الاستخدام الآمن للأجهزة المخصصة لحسابات التواصل الاجتماعي والمحافظة عليها وحمايتها. وعدم احتوائها على بيانات مصنفة أو استخدامها لأغراض شخصية.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-2', 'التعامل الآمن مع هويات الدخول وكلمات المرور والأسئلة الأمنية.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-3', 'خطة استعادة حسابات التواصل الاجتماعي والتعامل مع الحوادث السيبرانية.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-4', 'التعامل الآمن مع التطبيقات والحلول المستخدمة لحسابات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-5', 'عدم استخدام حسابات التواصل الاجتماعي الرسمية لأغراض شخصية مثل التصفح.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-6', 'تجنب الدخول لحسابات التواصل الاجتماعي باستخدام أجهزة أو شبكات عامة غير موثوقة.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-7', 'التواصل مباشرة مع الإدارة المعنية بالأمن السيبراني في الجهة حال الاشتباه بتهديد أمن سيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '14', NULL, '1-4-1'),
  ('OSMACC', '1-4-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-4 في الضوابط الأساسية للأمن السيبراني، فإنه يجب تدريب العاملين المسؤولين عن إدارة حسابات التواصل الاجتماعي للجهة على المهارات التقنية والخطط والإجراءات اللازمة لضمان تطبيق متطلبات وممارسات الأمن السيبراني عند استخدام حسابات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'control', '14', NULL, NULL),
  ('OSMACC', '2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15', NULL, NULL),
  ('OSMACC', '2-1-1-1', 'إدارة الأصول - 2-1-1-1', 'يجب تحديد وحصر حسابات التواصل الاجتماعي والأصول المعلوماتية والتقنية المتعلقة بها، وتحديثها مرة واحدة، كل سنة؛ على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '15', NULL, '2-1-1'),
  ('OSMACC', '2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات لحسابات التواصل الاجتماعي للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '15-16', NULL, NULL),
  ('OSMACC', '2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'استخدام حسابات التواصل الاجتماعي المخصصة للجهات، وليس الأفراد.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'التسجيل باستخدام معلومات رسمية (بريد إلكتروني رسمي خاص لوسائل التواصل الاجتماعي ورقم جوال رسمي)، وعدم استخدام معلومات شخصية.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'توثيق حسابات التواصل الاجتماعي والمحافظة على هوية متسقة في جميع حسابات التواصل الاجتماعي المستخدمة؛ لتسهيل معرفة الحسابات الرسمية، واكتشاف حسابات الاحتيال.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-4', 'إدارة هويات الدخول والصلاحيات - 2-2-1-4', 'استخدام كلمة مرور آمنة وخاصة لكل حسابات التواصل الاجتماعي وتغيير كلمة المرور بشكل دوري، وعدم إعادة استخدام كلمة مرور تم استخدامها من قبل.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-5', 'إدارة هويات الدخول والصلاحيات - 2-2-1-5', 'استخدام التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) لعمليات الدخول لحسابات التواصل الاجتماعي.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-6', 'إدارة هويات الدخول والصلاحيات - 2-2-1-6', 'تفعيل وتحديث الأسئلة الأمنية وتوثيقها في مكان آمن.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-7', 'إدارة هويات الدخول والصلاحيات - 2-2-1-7', 'إدارة صلاحيات المستخدمين لحسابات التواصل الاجتماعي بناءً على احتياجات العمل، مع مراعاة حساسية الحسابات ومستوى الصلاحيات، ونوعية الأجهزة والأنظمة المستخدمة.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-8', 'إدارة هويات الدخول والصلاحيات - 2-2-1-8', 'حصر صلاحيات مقدمي خدمة إدارة حسابات التواصل الاجتماعي أو المراقبة الآلية لحسابات التواصل الاجتماعي أو حماية هوية الجهة من الانتحال.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-1-9', 'إدارة هويات الدخول والصلاحيات - 2-2-1-9', 'حصر إمكانية الدخول لحسابات التواصل الاجتماعي للجهة من أجهزة محددة.', 'تعزيز الأمن السيبراني', 'sub_control', '15-16', NULL, '2-2-1'),
  ('OSMACC', '2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط الفرعي 2-2-3-5 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول والصلاحيات المستخدمة لحسابات التواصل الاجتماعي للجهة، بحد أدنى مرة واحدة كل سنة.', 'تعزيز الأمن السيبراني', 'control', '15-16', NULL, NULL),
  ('OSMACC', '2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-3-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية حسابات التواصل الاجتماعي للجهة، والأصول التقنية الخاصة بها، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16', NULL, NULL),
  ('OSMACC', '2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'تطبيق حزم التحديثات، والإصلاحات الأمنية لتطبيقات التواصل الاجتماعي، مرة واحدة شهرياً على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-3-1'),
  ('OSMACC', '2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'مراجعة إعدادات الحماية والتحصين لحسابات التواصل الاجتماعي للجهة والأصول التقنية الخاصة بها (Secure Configuration and Hardening)، مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-3-1'),
  ('OSMACC', '2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'مراجعة وتحصين الإعدادات المصنعية (Default Configuration) لحسابات التواصل الاجتماعي والأصول التقنية، ومنها وجود كلمات مرور ثابتة أو تسجيل الدخول المسبق، وإقفال الأجهزة (Lockout).', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-3-1'),
  ('OSMACC', '2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'تقييد تفعيل الخصائص والخدمات في حسابات التواصل الاجتماعي حسب الحاجة، على أن يتم تحليل المخاطر السيبرانية المحتملة في حال الحاجة لتفعيلها.', 'تعزيز الأمن السيبراني', 'sub_control', '16', NULL, '2-3-1'),
  ('OSMACC', '2-4-1', 'أمن الأجهزة المحمولة - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة لحسابات التواصل الاجتماعي للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '16-17', NULL, NULL),
  ('OSMACC', '2-4-1-1', 'أمن الأجهزة المحمولة - 2-4-1-1', 'إدارة الأجهزة المحمولة مركزياً باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management - MDM).', 'تعزيز الأمن السيبراني', 'sub_control', '16-17', NULL, '2-4-1'),
  ('OSMACC', '2-4-1-2', 'أمن الأجهزة المحمولة - 2-4-1-2', 'تطبيق حزم التحديثات، والإصلاحات الأمنية للأجهزة المحمولة، مرة واحدة شهرياً، على الأقل.', 'تعزيز الأمن السيبراني', 'sub_control', '16-17', NULL, '2-4-1'),
  ('OSMACC', '2-5-1', 'حماية البيانات والمعلومات - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-7-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات لحسابات التواصل الاجتماعي للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('OSMACC', '2-5-1-1', 'حماية البيانات والمعلومات - 2-5-1-1', 'يجب أن لا تحتوي الأصول التقنية الخاصة بحسابات التواصل الاجتماعي للجهة على بيانات مصنفة، حسب التشريعات ذات العلاقة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-5-1'),
  ('OSMACC', '2-6-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني لحسابات التواصل الاجتماعي للجهة والأصول التقنية التابعة لها، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '17', NULL, NULL),
  ('OSMACC', '2-6-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-1', 'تفعيل جميع الإشعارات وتنبيهات الأمن السيبراني الخاصة بحسابات التواصل الاجتماعي وسجلات الأحداث (Event Logs) الخاصة بالأمن السيبراني على الأصول التقنية الخاصة بحسابات التواصل الاجتماعي.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-6-1'),
  ('OSMACC', '2-6-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-2', 'متابعة حسابات التواصل الاجتماعي ومراقبتها للتأكد من عدم نشر أي محتوى غير مصرح، أو تسجيل أي دخول غير مصرح.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-6-1'),
  ('OSMACC', '2-6-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-3', 'متابعة شبكات التواصل الاجتماعي ومراقبتها للتأكد من عدم انتحال هوية الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-6-1'),
  ('OSMACC', '2-6-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-4', 'المراقبة الآلية لأي تغيير في نمط الحسابات أو مؤشرات اختراق أو نشر أي محتوى غير مصرح أو انتحال هوية الجهة.', 'تعزيز الأمن السيبراني', 'sub_control', '17', NULL, '2-6-1'),
  ('OSMACC', '2-7-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-13-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'control', '18', NULL, NULL),
  ('OSMACC', '2-7-1-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-7-1-1', 'وضع خطة استعادة حسابات التواصل الاجتماعي والتعامل مع الحوادث السيبرانية.', 'تعزيز الأمن السيبراني', 'sub_control', '18', NULL, '2-7-1'),
  ('OSMACC', '3-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1', 'يجب تقييم مدى الحاجة لاستخدام خدمات إدارة حسابات التواصل الاجتماعي (social media management) والمراقبة الآلية لحسابات التواصل الاجتماعي أو لحماية هوية الجهة من الانتحال (brand protection) ومخاطر الأمن السيبراني المتعلقة بها.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '18', NULL, NULL),
  ('OSMACC', '3-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 4-1-2 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات إدارة حسابات التواصل الاجتماعي (social media management) والمراقبة الآلية لحسابات التواصل الاجتماعي أو لحماية هوية الجهة من الانتحال (brand protection)، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', '18', NULL, NULL),
  ('OSMACC', '3-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-1', 'بنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) والحذف الآمن من قبل الطرف الخارجي لبيانات الجهة عند انتهاء الخدمة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '18', NULL, '3-1-2'),
  ('OSMACC', '3-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-2', 'إجراءات التواصل للإبلاغ عن الثغرات وفي حال اكتشاف حادثة أمن سيبراني.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '18', NULL, '3-1-2'),
  ('OSMACC', '3-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-3', 'إلزام الطرف الخارجي بتطبيق متطلبات وسياسات الأمن السيبراني لحماية حسابات التواصل الاجتماعي للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '18', NULL, '3-1-2'),
  ('CCC', '1-1-P-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-1-P-1', 'بالإضافة للضابط 1-4-1 في الضوابط الأساسية للأمن السيبراني، يجب على صاحب الصلاحية تحديد وتوثيق واعتماد ما يلي:', 'حوكمة الأمن السيبراني', 'control', '13', 'CSP', NULL),
  ('CCC', '1-1-P-1-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-1-P-1-1', 'أدوار الأمن السيبراني، وتكليفات المسؤولية والمحاسبة والاستشارة والتبليغ (RACI) لكل أصحاب العلاقة في خدمات الحوسبة السحابية، بما في ذلك أدوار ومسؤوليات صاحب الصلاحية.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CSP', '1-1-P-1'),
  ('CCC', '1-1-T-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-1-T-1', 'بالإضافة للضابط 1-4-1 في الضوابط الأساسية للأمن السيبراني، يجب على صاحب الصلاحية تحديد وتوثيق واعتماد ما يلي:', 'حوكمة الأمن السيبراني', 'control', '13', 'CST', NULL),
  ('CCC', '1-1-T-1-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-1-T-1-1', 'أدوار الأمن السيبراني، وتكليفات المسؤولية والمحاسبة والاستشارة والتبليغ (RACI) لكل أصحاب العلاقة في خدمات الحوسبة السحابية، بما في ذلك أدوار ومسؤوليات صاحب الصلاحية.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CST', '1-1-T-1'),
  ('CCC', '1-2-P-1', 'إدارة مخاطر الأمن السيبراني - 1-2-P-1', 'يجب أن تتضمن منهجية إدارة مخاطر الأمن السيبراني المذكورة في المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني لدى مقدمي الخدمات بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '13', 'CSP', NULL),
  ('CCC', '1-2-P-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-P-1-1', 'تحديد المستوى المقبول للمخاطر (Acceptable Risk Levels) فيما يتعلق بخدمات الحوسبة السحابية، وتوضيحها للمشترك إذا كانت المخاطر ذات علاقة به.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CSP', '1-2-P-1'),
  ('CCC', '1-2-P-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-P-1-2', 'أخذ تصنيف البيانات والمعلومات بالاعتبار في منهجية إدارة مخاطر الأمن السيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CSP', '1-2-P-1'),
  ('CCC', '1-2-P-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-P-1-3', 'إنشاء سجل لمخاطر الأمن السيبراني خاص بالعمليات وخدمات الحوسبة السحابية، ومتابعته دوريًا بما يتناسب مع طبيعة المخاطر.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CSP', '1-2-P-1'),
  ('CCC', '1-2-T-1', 'إدارة مخاطر الأمن السيبراني - 1-2-T-1', 'يجب أن تتضمن منهجية إدارة مخاطر الأمن السيبراني المذكورة في المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني لدى المشتركين بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '13', 'CST', NULL),
  ('CCC', '1-2-T-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-T-1-1', 'تحديد المستوى المقبول للمخاطر (Acceptable Risk Levels) فيما يتعلق بخدمات الحوسبة السحابية.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CST', '1-2-T-1'),
  ('CCC', '1-2-T-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-T-1-2', 'أخذ تصنيف البيانات والمعلومات بالاعتبار في منهجية إدارة مخاطر الأمن السيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CST', '1-2-T-1'),
  ('CCC', '1-2-T-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-T-1-3', 'إنشاء سجل لمخاطر الأمن السيبراني خاص بالعمليات وخدمات الحوسبة السحابية، ومتابعته دوريًا بما يتناسب مع طبيعة المخاطر.', 'حوكمة الأمن السيبراني', 'sub_control', '13', 'CST', '1-2-T-1'),
  ('CCC', '1-3-P-1', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني - 1-3-P-1', 'بالإضافة للضابط 1-7-1 في الضوابط الأساسية للأمن السيبراني، يجب أن يشتمل التزام مقدمي الخدمات بالمتطلبات التشريعية والتنظيمية بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-3-P-1-1', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني - 1-3-P-1-1', 'الالتزام الدائم والمستمر بجميع الأنظمة واللوائح والتعليمات والقرارات والأطر والضوابط التنظيمية المتعلقة بالأمن السيبراني المعمول بها في المملكة.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-3-P-1'),
  ('CCC', '1-3-T-1', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني - 1-3-T-1', 'بالإضافة للضابط 1-7-1 في الضوابط الأساسية للأمن السيبراني، يجب أن يشتمل التزام المشتركين بالمتطلبات التشريعية والتنظيمية بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CST', NULL),
  ('CCC', '1-3-T-1-1', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني - 1-3-T-1-1', 'المراقبة الدائمة والمستمرة لمدى التزام مقدمي الخدمات بالتشريعات، وبنود العقود المتعلقة بالأمن السيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CST', '1-3-T-1'),
  ('CCC', '1-4-P-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابطين 1-9-3 و 1-9-4 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني قبل بدء العلاقة المهنية بين العاملين ومقدمي الخدمة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-4-P-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-1-1', 'فيما يتعلق بمراكز البيانات التابعة لمقدم الخدمة داخل المملكة، يجب أن يشغل وظائف الأمن السيبراني للحوسبة السحابية داخل المملكة مواطنون سعوديون مؤهلون.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-4-P-1'),
  ('CCC', '1-4-P-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-1-2', 'إجراء المسح الأمني للعاملين داخل المملكة الذين لهم حق الوصول إلى الأنظمة التقنية السحابية (Cloud Technology Stack (CTS)) دوريًا.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-4-P-1'),
  ('CCC', '1-4-P-1-3', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-1-3', 'إقرار وتوقيع العاملين على جميع سياسات الأمن السيبراني كشرط مسبق للوصول إلى الأنظمة التقنية السحابية (CTS).', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-4-P-1'),
  ('CCC', '1-4-P-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-9-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني بعد انتهاء العلاقة المهنية بين العاملين ومقدمي الخدمة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-4-P-2-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-P-2-1', 'ضمان إعادة الأصول الخاصة بمقدمي الخدمات (لا سيما ذات الصلة بالأمن السيبراني) بمجرد إنهاء الخدمة مع العاملين.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-4-P-2'),
  ('CCC', '1-4-T-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-T-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-9-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني قبل بدء العلاقة المهنية بين العاملين والمشتركين، بحد أدنى، ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CST', NULL),
  ('CCC', '1-4-T-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-4-T-1-1', 'إجراء المسح الأمني للعاملين الذين لهم حق الوصول إلى المهام الحساسة لخدمات الحوسبة السحابية، مثل: إدارة المفاتيح، إدارة الخدمات، التحكم بالوصول (Access Control).', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CST', '1-4-T-1'),
  ('CCC', '1-5-P-1', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-1', 'يجب تحديد متطلبات الأمن السيبراني لإدارة التغيير لدى مقدمي الخدمات، وتوثيقها، واعتمادها.', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-5-P-2', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بإدارة التغيير لدى مقدمي الخدمات.', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-5-P-3', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-3', 'يجب أن يغطي الأمن السيبراني لإدارة التغيير لدى مقدمي الخدمات بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '1-5-P-3-1', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-3-1', 'إجراءات تنفيذ التغييرات (المخطط لها) بطرق آمنة، في أنظمة الإنتاج (Production Systems)، مع إعطاء أولوية للملاحظات المتعلقة بالأمن السيبراني.', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-5-P-3'),
  ('CCC', '1-5-P-3-2', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-3-2', 'إجراءات تنفيذ التغييرات الاستثنائية ذات العلاقة بالأمن السيبراني (مثل التغييرات أثناء التعافي من الحوادث).', 'حوكمة الأمن السيبراني', 'sub_control', '14', 'CSP', '1-5-P-3'),
  ('CCC', '1-5-P-4', 'الأمن السيبراني ضمن إدارة التغيير - 1-5-P-4', 'يجب مراجعة متطلبات الأمن السيبراني لإدارة التغيير لدى مقدمي الخدمات، ومراجعة تطبيقها، دوريًا.', 'حوكمة الأمن السيبراني', 'control', '14', 'CSP', NULL),
  ('CCC', '2-1-P-1', 'إدارة الأصول - 2-1-P-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية لدى مقدمي الخدمات، بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '16', 'CSP', NULL),
  ('CCC', '2-1-P-1-1', 'إدارة الأصول - 2-1-P-1-1', 'حصر جميع الأصول المعلوماتية والتقنية باستخدام التقنيات المناسبة كقاعدة بيانات إدارة الإعدادات (CMDB)، أو قدرة مماثلة، تتضمن جردًا لكل الأصول التقنية.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '16', 'CSP', '2-1-P-1'),
  ('CCC', '2-1-P-1-2', 'إدارة الأصول - 2-1-P-1-2', 'تحديد ملاك الأصول (Asset Owners) وإشراكهم في دورة حياة إدارة الأصول.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '16', 'CSP', '2-1-P-1'),
  ('CCC', '2-1-T-1', 'إدارة الأصول - 2-1-T-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية لدى المشتركين، بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '16', 'CST', NULL),
  ('CCC', '2-1-T-1-1', 'إدارة الأصول - 2-1-T-1-1', 'حصر جميع الخدمات السحابية والأصول المعلوماتية والتقنية المتعلقة بها.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '16', 'CST', '2-1-T-1'),
  ('CCC', '2-10-P-1', 'اختبار الاختراق - 2-10-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-11-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باختبار الاختراق لدى مقدمي الخدمات، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '20', 'CSP', NULL),
  ('CCC', '2-10-P-1-1', 'اختبار الاختراق - 2-10-P-1-1', 'يجب أن يشمل نطاق عمل اختبار الاختراق الأنظمة التقنية السحابية (CTS)، وأن يتم عمل اختبار الاختراق كل ستة أشهر؛ على الأقل.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '20', 'CSP', '2-10-P-1'),
  ('CCC', '2-11-P-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة سجلات الأحداث ومراقبة الأمن السيبراني لدى مقدمي الخدمات، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '21', 'CSP', NULL),
  ('CCC', '2-11-P-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-1', 'تفعيل وحماية سجلات الأحداث (Event Logs) والتدقيق (Audit Trial) للأنظمة التقنية السحابية (CTS).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-2', 'تفعيل سجلات الأحداث الخاصة بمحاولات عمليات الدخول (Login) وجمعها.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-3', 'تفعيل وحماية سجلات الأحداث لجميع الأنشطة والعمليات التي يقوم بها مقدم الخدمة على أنظمة المشتركين، بهدف دعم عمليات التحليل الرقمي الجنائي (Digital Forensics).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-4', 'حماية سجلات الأحداث (Event Logs) الخاصة بالأمن السيبراني، من الوصول غير المصرح به، أو العبث، أو التغيير، أو الحذف غير المشروع، وذلك وفقًا للمتطلبات التشريعية أو التنظيمية.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-5', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-5', 'المراقبة الأمنية المستمرة لأحداث الأمن السيبراني (Cybersecurity Events) باستخدام تقنيات (SIEM) بحيث تشمل جميع الأحداث المتعلقة بالأنظمة التقنية السحابية (CTS).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-6', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-6', 'المراجعة الدورية لسجلات الأحداث (Event Logs) والتدقيق (Audit Trail) بحيث تشمل الأحداث والسجلات المتعلقة بالأنظمة التقنية السحابية (CTS)، التي تم تنفيذها من قبل مقدم الخدمة.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-7', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-7', 'استخدام وسائل آلية لمراقبة سجلات الأحداث الخاصة بعمليات الدخول عن بعد (Remote Access).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-P-1-8', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-P-1-8', 'التعامل الآمن مع بيانات المستخدمين المتواجدة في سجلات الأحداث (Event Logs) والتدقيق (Audit Trails) وسجلات أحداث الأمن السيبراني (Cybersecurity Events Logs).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-11-P-1'),
  ('CCC', '2-11-T-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-T-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة سجلات الأحداث ومراقبة الأمن السيبراني لدى المشتركين، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '21', 'CST', NULL),
  ('CCC', '2-11-T-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-T-1-1', 'تفعيل وجمع سجلات الأحداث الخاصة بعمليات الدخول (Login)، وسجلات الأحداث الخاصة بالأمن السيبراني المتعلقة بالأصول على الخدمات السحابية.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CST', '2-11-T-1'),
  ('CCC', '2-11-T-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-T-1-2', 'أن تشمل عملية المراقبة جميع أحداث الأمن السيبراني المفعلة على الخدمات السحابية الخاصة بالمشترك.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CST', '2-11-T-1'),
  ('CCC', '2-12-P-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-13-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة حوادث وتهديدات الأمن السيبراني لدى مقدمي الخدمات، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '21', 'CSP', NULL),
  ('CCC', '2-12-P-1-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-1', 'الاشتراك مع المجموعات والجهات المتخصصة والموثوقة للحصول على آخر التهديدات والمستجدات في مجال الأمن السيبراني.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-2', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-2', 'تدريب العاملين (موظفين ومتعاقدين) على الاستجابة لحوادث الأمن السيبراني بما يتماشى مع الأدوار والمسؤوليات.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-3', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-3', 'اختبار قدرات الاستجابة لحوادث الأمن السيبراني دوريًا.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-4', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-4', 'تحليل وتحديد الأسباب الجذرية (Root Cause Analysis) لحوادث الأمن السيبراني، ووضع الخطط الكفيلة بمعالجتها.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-5', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-5', 'تقديم الدعم إلى المشتركين في حالات القضايا القانونية، والتحليل الرقمي الجنائي، والحفاظ على الأدلة الرقمية التي تقع تحت إدارة ومسؤولية مقدم الخدمة حسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-6', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-6', 'تبليغ المشترك بشكل فوري عن حوادث الأمن السيبراني التي قد تؤثر عليه، في حال اكتشاف الحادثة.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-7', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-7', 'دعم المشتركين للتعامل مع حوادث الأمن السيبراني حسب الاتفاقية مابين مقدم الخدمة والمشترك.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-12-P-1-8', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-P-1-8', 'قياس ومراقبة مؤشرات الأداء الخاصة بإدارة حوادث الأمن السيبراني، ومراقبة مدى الالتزام بمتطلبات العقود والتشريعات.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '21', 'CSP', '2-12-P-1'),
  ('CCC', '2-13-P-1', 'الأمن المادي - 2-13-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-14-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بالأمن المادي لدى مقدمي الخدمات، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '22', 'CSP', NULL),
  ('CCC', '2-13-P-1-1', 'الأمن المادي - 2-13-P-1-1', 'المراقبة المستمرة لعمليات الدخول والخروج للمباني والمواقع لدى مقدم الخدمة.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '22', 'CSP', '2-13-P-1'),
  ('CCC', '2-13-P-1-2', 'الأمن المادي - 2-13-P-1-2', 'منع الوصول غير المصرح به للأجهزة التي تتعامل مباشرة مع الأنظمة التقنية السحابية (CTS).', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '22', 'CSP', '2-13-P-1'),
  ('CCC', '2-13-P-1-3', 'الأمن المادي - 2-13-P-1-3', 'التخلص الآمن من أجهزة البنية التحتية (Infrastructure Hardware)، وبالأخص معدات التخزين (Storage Equipments) باتباع أفضل الممارسات والتشريعات ذات العلاقة.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '22', 'CSP', '2-13-P-1'),
  ('CCC', '2-14-P-1', 'حماية تطبيقات الويب - 2-14-P-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-15-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بحماية تطبيقات الويب لدى مقدمي الخدمات، بحد أدنى مايلي:', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '22', 'CSP', NULL),
  ('CCC', '2-14-P-1-1', 'حماية تطبيقات الويب - 2-14-P-1-1', 'حماية المعلومات المستخدمة عن طريق إجراء المعاملات في تطبيقات الويب من المخاطر المحتملة، مثل: انقطاع الاتصال (Incomplete Transmission)، التوجيه الخاطئ (Mis-routing)، التعديل غير المصرح به، الاطلاع غير المصرح به.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'sub_control', '22', 'CSP', '2-14-P-1'),
  ('CCC', '2-15-P-1', 'إدارة المفاتيح - 2-15-P-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة بعملية إدارة المفاتيح لدى مقدمي الخدمات.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '22', 'CSP', NULL),
  ('CCC', '2-15-P-2', 'إدارة المفاتيح - 2-15-P-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بعملية إدارة المفاتيح لدى مقدمي الخدمات.', 'تعزيز الأمن السيبراني (Cybersecurity Defense) — pdf p.16+ [17 subdomains — the framework''s largest domain]', 'control', '22', 'CSP', NULL),
