)
-- NOTE: hierarchy_level is intentionally inserted as 'control' for every
-- row here (even true sub-controls) with parent_control_id left null, to
-- satisfy controls_hierarchy_parent_check at insert time (Postgres CHECK
-- constraints cannot be DEFERRABLE). Pass 3 below flips hierarchy_level to
-- 'sub_control' and sets parent_control_id together, in the same UPDATE,
-- for every true sub-control — satisfying the constraint at that point too.
insert into public.controls (framework_id, control_code, title_ar, description_ar, official_text_ar, domain_ar, hierarchy_level, source_page, applicability, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, cat.control_code, cat.title_ar, cat.official_text_ar, cat.official_text_ar, cat.domain_ar, 'control', cat.source_page, cat.applicability, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from catalog cat
join public.frameworks f on f.code = cat.framework_code
on conflict (framework_id, control_code) do update set
  official_text_ar = excluded.official_text_ar,
  source_page = excluded.source_page,
  applicability = excluded.applicability;

