update public.controls child
set parent_control_id = parent.id,
    hierarchy_level = 'sub_control'
from sub_parent sp
join public.frameworks f on f.code = sp.framework_code
join public.controls parent on parent.framework_id = f.id and parent.control_code = sp.parent_code
where child.framework_id = f.id
  and child.control_code = sp.control_code
  and (child.parent_control_id is distinct from parent.id or child.hierarchy_level is distinct from 'sub_control');
